INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Jonchon, sifat bo\'la shodig\'ar va qimmatbaho o\'tloqlardan biri bo\'lib, chorvachilik sanoatida doim dehqonlarning ekish ustuvorligi bo\'lgan. Lekin asosiy muammo doim shu bo\'lgan: yer metridan maksimal samaradorlikni qanday olish mumkin? <strong>Jonchon hektar mahsuloti tape suqorotida</strong> Ushbu savolning javobini berishi mumkin. Bu yangi suqorot usuli suv va oziq moddalarni to\'g\'ridan-to\'g\'ri ildizlar tomon aniq taqsim etib o\'simlik o\'sish potensialini maksimal darajaga ko\'taradi. Davomida, ideal samaradorlikga erishish uchun texnik va amaliy tafsilotlarni ko\'rib chiqamiz.</p>\n\n<h2>Maksimal samaradorlik uchun jonchon ekish prinsiplari bilan tanishish</h2>\n<p>Suqorot tizimi haqida gapirishdan oldin, o\'simlikning genetik potensialini mahsulot cheklovidagi asosiy belgilovchi sifatida bilish kerak. Oq, yashil va lova jonchoni keng tarqalgan turlardir, ularning har biri turli samaradorlikka ega. O\'rtacha hisobda, yashil jonchon ideal hududlarda yiliga 35-40 tondagi 6-8 kesim berishi mumkin. Lekin namlikni to\'g\'ri boshqarishsiz, bu raqamlar keskin pasayadi.</p>\n<p>Sifatli va sog\'lom donni ishlatish asosiy shart. Ekiladigan don miqdori tuproq turi va hudud iqlimiga mos bo\'lishi kerak. Haddan tashqari ko\'p ekish o\'simliklar ichki raqobatiga va har bir qurg\'uning kichrayishiga olib keladi. Don zichligini optimallashtirish bir xil va unumdor jamoaga erishish uchun birinchi qadam hisoblanadi.</p>\n\n\n\n<h2>Jonchon namlik boshqaruvidagi tape suqorot tizimining roli</h2>\n<p>Tape suqorot qatqoqli suqorot tizimlari to\'plamiga kiradi va plastmassa tasmadagi o\'ralgan oraliqlar orqali suvni sovituvchi va nazorat qilingan pichiq shaklida ildizlar tomonga yo\'naltiradi. Bu usul doimiy va bir xil namlik talab qiluvchi jonchon uchun ajoyibdir.</p>\n<p>Бузурги бешубҳаи ин система кам кардани бухоршавӣ ва талафоти об мебошад. Дар оғозии супоҳӣ то 50 фоиз оби метавонад бухор шуда ё ба офтоб пароканда шавад, аммо дар системаи напорӣ, об ҳатто дар марҳилаи қабатии ҷусур бошад, ба замини атрофи реша ворид мешавад. Ин боиси ин аст, ки решаҳо дар муҳити намнок боқӣ мемонанд, бе иллат кардани зиёд, ки боиси бемориҳои решагард шуда, боис мешавад. Агар хоҳед, ки напарии себрро бо қунҷит муқоиса кунед, чунин система лозим аст, ки чун решаҳои ин ғалладорӣ амиқтар ва фаъолтар аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-یونجه-در-هکتار-با-نوار-تیپ-تصویر-شاخص.webp" alt="میزان برداشت یونجه در هکتار با نوار تیپ - تصویر 1"/><figcaption>босери ҳеқтар оғози напории қунҷит</figcaption></figure>\n\n<h3>Брамдории оғози барои рӯшании тезтар</h3>\n<p>Қунҷит ба ҳобори доимии оғоз лозим аст. Системаи напорӣ имкон медиҳад, ки шумо 2-3 рӯз як бор миқдоре обро ворид кунед. Ин усули “оғози борикӣ бо тақсимкундагии паст” мебошад, ки намии заминро дар қабати фаъоли реша доимӣ нигоҳ медорад. Дар муқобил, оғози вазнин ва мавсимӣ боиси шакистани реша ва кам шудани ҳосили ҳар як қатъӣ мешавад. Барои муайян кардани нуқҳои дақиқтарини насб, омадани <a href="https://navar-abyari.ir/how-to-determine-tape-irrigation-points/">чӣ гуна нуқҳои напорӣ муайян мешаванд</a> ба шумо кӯмак мекунад, ки фарогирии якхоро дар тамоми майдонро таъмин кунед.</p>\n\n<h2>Таҳлили техникӣ ҳосили бардорӣ: чӣ гуна ба 35 тонна дар як ҳектар расем?</h2>\n<p>Расидан ба ҳосили зиёда аз 35 тонна дар як ҳектар ба ҳам афзалияти се омил вобаста аст: генетика, ғизо ва нам. Системаи напорӣ на танҳо об, балки ҳамчун канал барои андозадан дақиқи моддаҳои озува (фертёғатсия) хизмат мекунад. Ин хосият фарқии асосии ин система бо усулҳои анъанавӣ мебошад.</p>\n<p>Бо истифода аз системаи нӯрашӣ метавонед оддаҳои ғизоиро мустақиман ба минтакаи решаҳо инъикос кунед. Ин корро 50% дар оғоз ва 30% дар охирҳои фасли рушд илова мекунад, ки сарфи оддаҳо аз тавассути шӯйи обро кам мекунад. Юнҷа ба нитроген, фосфор ва потассий ҳассос аст. Инъикоси тадриҷии ин унсурҳо дар давоми фасли рушд боиси гулҳои торактар, рушди суръатбатар байни қатъҳо ва дар охир афзоиши <strong>даромади ҳосилии юнҷа дар гектар бо системаи нӯрашӣ</strong> мепайдо мешавад.</p>\n<ul>\n<li><strong>Афзоиши шумораи қатъ:</strong> Бо идоракунии беҳтари намнокӣ метавон дар баъзе минтақаҳо то 8 ё ҳатто 9 қатъ дар сол даст расид, дар ҳоле ки бо усули анъанавӣ одатан 6 қатъ имконпазир аст.</li>\n<li><strong>Кам шудани хароҷоти энергӣ:</strong> Баромади системаи нӯрашӣ нисбати чачакуноки анъанавӣ камтар аст, ки ин боиси сарфаи хароҷоти барқ мегардад.</li>\n<li><strong>Саломатии ғунҷоҳи ботинкӣ:</strong> Кам шудани бемориҳои қарчии барги барои қушк мондани поҳои решаи ҷунсонҳо, ки дар натиҷа кам шудани оташкунии меҳварӣ барои бемории меҳварӣ аст.</li>\n</ul>\n\n\n\n<h3>Таъсири иқлимӣ ба ҳосили риштаи нӯрӣ дар чароғӣ</h3>\n<p>Дар минтақаҳои хушк ва гарм, таҳдоди асосӣ идоракунии гармӣ аст. Риштаи нӯрӣ барои қарор гирифтани он дар сатҳи хок, баъзан бо бухоршавӣ аз сатҳи пластики мувоҷеҳ мешавад. Барои мукобида ба ин мушкил, пӯшишҳои иловагӣ ё тағйир додани суръати равон тавсия дода мешавад. Аз тарафи дигар, дар минтақаҳоинамҳо ва сард, идоракунии қарчҳо муҳимтар аст. Дар ин ҳолат, истифодаи суръати равони пасттар ва фосилаи бештар байни обёрӣҳо метавонад хатари шамолро кам кунад. Донистани хусусиятҳои умумии тizимҳо, масалан, хусусиятҳои физикии риштаи нӯрӣ, ба шумо кӯмак мекунад, то модели мувофиқтарро барои шартҳои махсуси деҳаи худ интихоб кунед.</p>\n\n<h2>Нигёҳубин ва нуктаҳои амалӣ барои нигоҳ доштани умри тizим</h2>\n<p>Яке аз бартарии калони риштаи нӯрӣ ҳароҷи нигоҳубини паст аст, аммо агар но дуруст идора шавад, бо суръати баланд ба гирдҳо ё пардашавӣ мерасад. Чароғӣ одатан дар сол қатори зиёди кардан дорад. Ҳар марҳила, ки чарм ё мошин мекарад, хатари осеб ба риштаи зери хок баланд мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-یونجه-در-هکتار-با-نوار-تیپ-کاربرد-عملی.webp" alt="میزان برداشت یونجه در هکتار با نوار تیپ - تصویر 2"/><figcaption>Ҳосили меҳварӣ дар ҳектар обёрӣ бо риштаи нӯрӣ чароғӣ</figcaption></figure>\n<ol>\n<li><strong>Таъмирҳои даврагӣ:</strong> Баъд аз ҳар як кардан, санҷиши бинӣ-нигории риштаҳо зарур аст. Ҳар як пичуқ бояд фавран бо часпҳои махсус ислоҳ шавад.</li>\n<li><strong>Шӯстанати филтрҳо:</strong> Филтрҳо бояд бо тартиб шуста шаванд, то ки зарраҳои чаргон ва хок даромада баромади хастагиҳо дар наворро бимонанд.</li>\n<li><strong>Гурӯҳкунии наворҳо:</strong> Наворҳоро дар гурӯҳҳои 10 то 15 метра ҷойгир кунед, то дар ҳолати хастагӣ зарур набошад, ки тамоми системаиро пӯшед.</li>\n</ol>\n<p>Барои зиёд кардани умри кории система, тавсия меёбад, ки аз дастрасии зиёд кардани умри кории навори дотирӣ истифода баред. Инчунин, интихоби намуди пластикӣ, ки ба теъсири UV тобдор аст, барои наворҳое, ки метавонанд чанд фавсон ба нӯри мустақим даромад кунанд, муҳим аст.</p>\n\n<h2>Бартарии иқтисодӣ: Оё навори дотирӣ барои чаргон сарфа кардан мумкин аст?</h2>\n<p>Кишовар ҳамеша баҳри баргардидани сармояш парҳез аст. Системаи навори дотирӣ нисбат ба навозиҳои одадии шӯрох (меш) арзонтар аст ва насби он зудтар анҷом дода мешавад. Бо ба назар гирифтани он, ки чаргон маҳсулоти бисёрсола аст (одатан 4 то 5 сол хатиронӣ мешавад), хараҷи ибтидоии системаи обкорӣ дар солҳои аввал бармегардад. Пурзӯр шудани самаранокӣ ва истеҳсолиро аз роҳи кам кардани истеъмол об (то 40 фоиз сарфа) ва одак, хараҷҳои амалиро паст меорад. Ба ин илова, зиёд шудани маҳсули сифатноктар ва хосусиятноктар, бевосита ба даромади кишовар меафтад.</p>\n\n\n\n<h2>Ҷавоб ба саволҳои маврӯтии зид</h2>\n<h3>Оя нории капи бар ҳама намудҳои бенафш мувофиқ аст?</h3>\n<p>Бале, нории капи бар бенафши сабз, сафед, зирка ва ҳатто бенафши амара (Alfalfa) хеле мувофиқ аст. Танҳо фарқият дар фосилаи насб ва оқими об аст, ки бояд вобаста ба синни растани танзим карда шавад. Дар марҳилаи растанӣ тавсия мешавад, ки оқим камтар бошад, то аз гардиши нории капи пешгирӣ карда шавад.</p>\n<h3>Оя имкон дорад, ки нории капиро бе задан ба решаҳои хурди бенафш истифода барем?</h3>\n<p>Тавсия мешавад, ки нории капи дар эҳотими 3 то 5 сантиметр зерини замин ва бо фосилаи 10 то 15 сантиметр аз сабуки растани гузоранда шавад. Ин амал аз зарбаи мустақими мошини чароинҳо ба нории капи пешгирӣ мекунад ва имкон медиҳад, ки решаҳо бе таъсири механикӣ рушд кунанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-یونجه-در-هکتار-با-نوار-تیپ-جزئیات-فنی.webp" alt="میزان برداشت یونجه در هکتار با نوار تیپ - تصویر 3"/><figcaption>productiivi бенафшро дар як гектар нории капи</figcaption></figure>\n<h3>Гулони нигоҳубини нории капи нисбат ба нории қаппакӣ чӣ қадар аст?</h3>\n<p>Гулони нигоҳубини нории капи одатан камтар аст, зеро қисмҳои ҳаракаткунанда барои ба банд омадан камтар дорад. Аммо он нисбат ба паҳшан хеле ҳассос аст. Агар шумо протоколи санҷиши ҳафтанаро риоя кунед, гурониҳо хеле паст мемонанд.</p>\n\n<h2>Хулоса ва тавсияҳои охирин</h2>\n<p>Истифодаи технологияи нарди китобӣ на танҳо як интихоби техникӣ, балки яке астратегия барои зиёд бақъаъпазири дар истеҳсоли чойпӯсти мебошад. Бо назардошти он ки хароҷоти об ва нӯк боқисари калонро ташкил медиҳанд, системаи обёрӣи дақиқ бевосита марҷи фоидаи шуморо зиёд мекунад. <strong>Ҳаҷми ғалами чойпӯсти дар як гектар бо нарди китобӣ</strong> Агар бо идоракунии дуруст бақшидан ва ошомонидан мувофиқат кунад, метавонад аз 25 тонна то беш аз 40 тонна дар як сол зиёд шавад.</p>\n<p>Тавсияи мо ба кӯҳконкорон ин аст, ки пеш аз оғози мавсими нав нақшаи нарди китобии худро боз дидабаррасӣ кунанд ва ҳосилнокии филтрҳои мувофиқро таъмин кунанд. Инчунин, омӯзиши принсипҳои амалии нарди пӯлодӣ (ки навъи дигари нарди китобӣ аст ва барои истифодаҳои махсустар истифода мешавад) метавонад диди шуморо дар бораи системаҳои навтарини обёрӣ васеъ кунад. Оғоз бо як лабораторияи хурд дар кунҷи хоҷагӣ ва назорати дақиқи маълумот дар бораи рушд беҳтарин сармоягузорӣ барои ояндаи корҳои деҳқонии шумост.</p>\n<p><strong>Мавзӯъҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/%D8%B4%D8%B1%D9%8A%D8%B7-%D8%A7%D9%84%D8%B1%D9%8A-%D8%A8%D8%A7%D9%84%D8%AA%D9%86%D9%82%D9%8A%D8%B7-%D9%81%D9%8A-%D8%AD%D9%84%D8%A8%DA%86%D9%87/">D8B4D8B1D98AD8B7 D8A7D984D8B1D98A D8A8D8A7D984D8AAD986D982D98AD8B7 D981D98A D8ADD984D8A8DA86D987</a>， <a href="https://navar-abyari.ir/%D8%A7%D9%86%D9%88%D8%A7%D8%B9-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C-%D9%82%D8%B7%D8%B1%D9%87-%D8%A7%DB%8C/">D8A7D986D988D8A7D8B9 D986D988D8A7D8B1 D8AADB8CD9BE D8A2D8A8DB8CD8A7D8B1DB8C D982D8B7D8B1D987 D8A7DB8C</a>， <a href="https://navar-abyari.ir/%d9%86%d8%ad%d9%88%d9%87-%d8%a7%d9%81%d8%b2%d8%a7%db%8c%d8%b4-%da%a9%d8%a7%d8%b1%d8%a7%db%8c%db%8c-%d9%88-%d8%a8%d9%87%d8%b1%d9%87%d9%88%d8%b1%db%8c-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c/">Чӣ гуна самаранокии нарди китобиро зиёд кардан мумкин аст</a></p>','Ҳосили пшавид аз як гектар бо навори тип: Раҳнамои оммавӣ барои баланд бардоштани истеҳсолот','Юнҷо яке аз муҳимтарин кормҳои равғанӣ ва фоиданок барои чорводони аст. Истифодаи технологияи обориши чоррӯявии тез метавонад самарануқсияи ин маҳсулотро ба таври назаррас зиёд кунад. Дар ин мақола мо баррасӣ мекунем, ки чӣ гуна бо идоракунии дуруст ҳосилнокии юнҷоро дар як гектарро тавассути обориши чоррӯявии тез ба қулла расонад.','publish','closed','closed','hosili-psavid-az-yek-gektar-bo-navori-tip',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
