INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин мақола усули истифодаи навори тип барои зиёд кардани ҳосили пшавид аз ҳар гектарро меомӯзед. Риёизомии техникӣ ва практикӣ барои кӯҳаксори истифодаи об ва баланд бардоштани рентабелии зироат барои кишоварзон.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
