INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррарот: Аҳамияти обёрории қатрагӣ дар парвариши нухӯд</h2>\n<p>Нухӯд яке аз нӯкифҳои истифодашаванда ва арзишманди ҳаризаи одамони тоҷик аст, ки ба идоракунии дақиқи захираҳои об ниёз дорад. Истифодаи системаҳои навосаҳои обёрӣ, хусусан <strong>навари тейпӣ</strong>, инқирози дар усулҳои обёрории нухӯд ба амал овардааст. Ин усул бо расонидани мустақими об ба реша на танҳо пешгирии тозаҳи обои мекунад, балки боиси рушди якхелаи растани ва зиёд гардидани сифати маҳсулот мегардад. Аммо муваффақият дар ин система танҳо ба харидани нвар хат намешиканад; балки <em>нигоҳдории нухӯд бо нвар тейпӣ</em> ва идоракунии дурусти равандҳо калиди даст ёбидан ба самаранокии баланд аст.</p>\n<p>Бисёр деҳқонон дилгиранд, ки нвар тейпӣ ба рушди растани чӣ таъсир мерасонад ва чӣ гуна бояд аз маҳшур шудани он пешгирӣ кунанд. Дар пайгиш, ба баррасии нуқтаҳои калидии нигоҳдории, принсипҳои техникӣ кӯрпӣ ва идоракунии система мегардзем, то ки шумо аз тамоми имкониятҳои ин усул ба фоида бароед.</p>\n\n<h2>Принсипҳои техникӣ интихоб ва насби нвар тейпӣ барои нухӯд</h2>\n<h3>Интихоби масофаи шитобиюн ва ҷойгиркунии паррандагӣ</h3>\n<p>Як аз муҳимтарин қисмҳои <strong>парвариши бобак бо шитобиюни типӣ</strong> , интихоби масофаи мувофиқи шитобиюн аз сутунҳои паррандагӣ мебошад. Бобак гиёҳест, ки решаҳои сатҳӣ дорад ва ба обёрӣи баҳраи кам ва мунтазам ниёз дорад. Одатан тавсия дода мешавад, ки шитобиюни типӣ дақиқан дар миёнаи масофаи ду сутуни бобак ё дар ҳаҷми 5 то 10-сантиметрии зер сатҳи хок ва дар самти параллел бо сутунҳо ҷойгир бошад. Барои шиносӣ бо меъёрҳои беҳтарини коркунӣ, таҳлили роҳнамои <a href="https://navar-abyari.ir/bean-strip-spacing-optimal-cultivation-standard/" target="_blank">масофаи шитобиюни бобак ва меъёрҳои паррандагӣ</a> метавонад диди шуморо дар бораи намунаҳои дурусти ҷойгиркунӣ васеъ соҳад.</p>\n<ul>\n<li><strong>Шитобиюн дар сатҳи хок:</strong> Барои гиёҳони ҷавон, ҷойгир кардани шитобиюн дар сатҳи хок ва наздикии дарахт хатарҳои сӯзонидан ва бемориҳои зидди зангорро зиёд мекунад. Бинобар ин, кофтани туннелҳои хурд ё маҳшукордани шитобиюн дар ҳаҷми кам зарур аст.</li>\n<li><strong>Роҳи ҷарроҳии лӯлаҳо:</strong> Тамаъмун шавед, ки роҳи пӯлод аз ҷои манбаи об то охири замин ҳамвор бошад, то аз ҳалқаи (loop) шудани пӯлод пешгирӣ кунед; зеро ин боиси фишори манфӣ ва дохил шудани ҳаво ба система мегардад.</li>\n</ul>\n\n<h3>Интихоби намуди мувофиқи пӯлодҳои дарёзӣ</h3>\n<p>Интихоби мавод вағафияти пӯлодҳои дарёзӣ ба давомнокии система ва хароҷотҳои доимӣ таъсири мустақим дорад. Барои бӯкоро (бақла) ки давраи ҳаёти баргаш тақрибан 120 то 150 рӯз аст, пӯлодҳо якдафъаи (Single-use) боғафияти 0.2 то 0.3 миллиметр интихоботи иқтисодӣ ва зиёд истифодашуда мебошанд. Аммо, агар наияд системаҳоро баръяд солҳои дигар истифода бароред, пӯлодҳои чанддафъаи боғафияти 0.4 миллиметр ё бештар мувофоттар аст. Барои шиносоӣ бо фарқиятҳои ин маҳсулот, шумо метавонед ба мақола <a href="https://navar-abyari.ir/navori-tipi-ob-yari-plakdor/" target="_blank">Муророти намудҳои пӯлодҳои дарёзӣ барои обёркунии ҷузъӣ (plakardor)</a> муроҷиат кунед. Ин дастур кӯмак мекунад, ки мувофиқи шартҳои иқлимӣ ва намуди хоки заминатон беҳтарин интихобро кунед.</p>\n\n[ [ [ I M A G E _ 1 ] ] ]\n\n<h2>Идоракунии фишори об ва сароии дар системаи пӯлодҳои дарёзӣ</h2>\n<h3>Оптимизатсияи фишори воридшаванда</h3>\n<p>Идоракунии фишори об, маркази ҳар як системаи абсёрӣи қатқорӣ ва навъи типасти мебошад. Ногун ба абсори баҳраву баҳраву ҳосилпазир ҳассос аст. Агар фишори об бисёр зиёд бошад, нави метавонад кушода шавад ё шустабӣ эҷод намояд ва агар фишор паст бошад, об ба охир нави намерасад ва таҳоввуми ғизоии растаниро дар охири раф бад меорад. Одатан фишори кори мувофиқ барои навҳои стандардӣ байни 0.5 то 2 бар мебошад. Истифодаи регулятори фишор дар ҷойи воридшавии система, қадами аввал барои <em>нигоҳубини дурусти нави</em> маҳсуб аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-باقلا-با-نوار-تیپ-نکات-کلیدی-تصویر-شاخص.webp" alt="نگهداری باقلا با نوار تیپ: نکات کلیدی - تصویر 1"/><figcaption>нигоҳубин ва тадбири нави абсори қатқорӣ барои ногун</figcaption></figure>\n<p>Инчунин, нишебии замин таъсири зиёде ба фишор мекушояд. Дар кӯрпавҳои нишебӣ бояд аз шаҳзодҳои танзими фишор ё тақсимоти блокҳои абсорӣ истифода бурд, то ки фарқи фишор дар ибтидо ва охири замин ба ҳадди ақал расад. Танзими но дурусти фишор метавонад ба абсории но муътадил ва кам шудани ҳосили ногун боис гардад.</p>\n\n<h2>Пешгирӣ аз боришкӣ ва ивазкунии нави</h2>\n<h3>Ҷудокунагону филтрҳои муҳим</h3>\n<p>Бориши сӯрохиҳои нави нави бо сабаби зараррасонидани зарраҳои муаллиқ дар об яке аз мушкилоти асосӣ дар <strong>Нигоҳдории нӯри нӯкиро бо риштаи дрип</strong> Филтри мувофиқ бояд мувофиқи андозаи сӯроҳҳои ришта (паймоор) интихоб шавад. Одатан, филтрҳои калибр бо паймоори 120 микрон барои риштаҳои сӯроҳи хурд мувофиқанд. Санҷиши мунтазами филтрҳо ва шустани вақтии онҳо аз хомӯшшавии ҷараёни об пешгирӣ мекунад.</p>\n<ul>\n<li>Истифодаи ҳалкундаҳои хлордор барои кушодани лӯлаҳо танҳо дар ҳолатҳои махсус ва бо машварати ихтисоскор иҷозат дорад.</li>\n<li>Ҷилавгирӣ аз дарозкундани кислотаҳои но мувофиқ, ки боиси таҷзияи полимери ришта мегарданд.</li>\n</ul>\n<p>Барои фаҳмиши беҳтарро дар бораи шустани ва нигоҳдории системаи лӯлакаширо, таҳқиқи дастурамали риштаи оли бо дрип дар Кирмон, ки қисмҳои нигоҳдории системаҳои даҳончаро бо тафсил муайян мекунад, муфид мебошад. Ин минтаҳообҳои қадима ва вақтан сахт доранд; бинобар ин, қоидаҳои ивазкунии риштаи оли бояд дақиқтар риоя шаванд.</p>\n\n<h2>Нуқтаҳои амалии обёрӣ кардани нӯкиро дар марҳалаҳои гуногуни афзоиш</h2>\n<h3>Обёрӣ кардан дар марҳалаи рӯӣшӣ ва гулдонӣ</h3>\n<p>Нӯкиро дар ду марҳалаи ҳисобии ба намӣ, яъне шубоҳои аввалин ва анборкунии ҳушвор, ниёзи махсус ба идоракунии риштаи дрип дорад. Дар марҳалаи гулдонӣ, обёрии пайваста бо рақобати кам боиси мешавад, ки набот кор сафеҳи худро барои афзоиши сабукӣ ва эҷоди донаҳои пурракуниш сарф кунад.</p>\n<table>\n<thead>\n<tr><th>Марҳаляи рушд</th><th>Нуқтаи муҳими лентарезии қатторӣ</th><th>Тавсияи амалӣ</th></tr>\n</thead>\n<tbody>\n<tr><td>Ҷавонкушӣ</td><td>Тақсими баробари об</td><td>Истифодаи лентарезӣ бо самаранокии мувофиқ барои намдории пурраи решаҳо</td></tr>\n<tr><td>Аз ҷавонкушӣ то гулӯкшӣ</td><td>Пешгирии афзоиши кӯлҳо</td><td>Борокиши стрип ё таъмини пӯшиш бо малч барои кам кардани рطобати сатҳ</td></tr>\n<tr><td>Ҷамъ кардани ҳосил</td><td>Устувори рطобат</td><td>Обёрӣи зиёд ва кӯтоҳ бо фишори доимӣ</td></tr>\n</tbody>\n</table>\n<p>Ё ин ки, масофагӣи бӯри хурма бар пояи намуди нӯхиш, нақши калидӣ дар ҳосилиат дорад. Барои ҳисобкунии дақиқи зичии ғаландоӣ, дастур <a href="https://navar-abyari.ir/drip-tape-for-beans-guide/" target="_blank">обёрӣи тамғаи бӯри хурма бо стрипи тамға</a> ро мустақимона омӯзед. Ин дастур ба шумо кӯмак мекунад то мувозинат байни зичии ғаландоӣ ва ҳаҷми оби расиданиро муайян кунед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-باقلا-با-نوار-تیپ-نکات-کلیدی-کاربرد-عملی.webp" alt="نگهداری باقلا با نوار تیپ: نکات کلیدی - تصویر 2"/><figcaption>crop drip tape maintenance care хурма</figcaption></figure>\n\n[ [ [ I M A G E _ 2 ] ] ]\n\n<h2>Идоракунии бемориҳо ва зараррасонувора бо истифода аз нарели</h2>\n<p>Яке аз барориши пинҳонӣ <strong>Нигоҳубини фасоло бо нарели</strong>， кам шудани намии нисбии равони хок ва эҷоди як қабати хушк байни ростҳо. Ин дар афзоиши тез қуморҳо ва камаронҳо даромад мебахшад. Аммо бо вуҷуди ин, хавфи бемориҳои рӯшноӣ ҳанӯз вуҷуд дорад. Истифодаи нарели ҳамчун тахтаи тирқунӣ (Fertigation) имкон медиҳад, ки моддаҳои ҳашаркуш ва қуморкуш ба таври мустақим ба рӯшноии аҳлиш рӯшношаванд ва аз шустани онҳо тавассути мезобон ё обгирӣ пешгирӣ кунанд. Бо вуҷуди ин, бояд диган кунед, ки ҳашарҳои интихоби бо мақулатии полимери нарели ҳамчун буд, зеро баъзе моддаҳои кимиёвӣ метавонанд боиси вайрон кардани нарезҳо шаванд.</p>\n<p>Истифодаи пушашҳо (Mulch) дар дона бо нарели ҳарорати хокро устувор мекунад ва аз шикастани нарезҳо боиси анбутшавӣ ва хунҷшавии илҳомии ғамзанда пешгирӣ мекунад. Ин бадаст овардан ба таври мухтасар дар минтақаҳои гармсиб, ки нарели рӯйи хок қарор дорад, бисёр муҳим аст. Барои ошношавӣ бо принсипҳои ниҳонгунӣ ва пушидан, ки мустақиман бо давомнокии нарели муташаккиф, метавонед ба намунаи интихоби нарели кунҷикӣ муроҷиат кунед.</p>\n\n<h2>Саволҳои одадӣ (FAQ) дар бораи обгирӣ фасоло</h2>\n<h3>Оё нарели барои хокҳои вазнин мувофиқ аст?</h3>\n<p>Ҳа, аммо бо эҳтиёт. Дар хокҳои лумӣ вазнин, нишастарӣ камтар аст. Эҳтимолан лозим аст, ки нарели бо даромади баландтар (деби) бошед то об ба чуқурии камол нокишад. Инчунин, чукурии насби нарезҳо наметавонад аз 15 сантиметр зиёд бошад то об ба рӯшноҳои сатҳи фасоло нарасад.</p>\n<h3>Чӣ тавр метавонам хӯни (гирдҳам шудани) тасмаи тибро шиносам?</h3>\n<p>Оз摩ини содатрасон, кушодани охири тасма ва мушоҳидаи ҷараёни об аст. Агар ҷараён қатъ шуда бошад ё оморданобӣ (ризиши об) равона бошад, тасма хӯнида аст. Дар ин ҳолат, шустани система бо фишори баланд ва истифодаи филтрҳои беҳтар тавсия мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-باقلا-با-نوار-تیپ-نکات-کلیدی-جزئیات-فنی.webp" alt="نگهداری باقلا با نوار تیپ: نکات کلیدی - تصویر 3"/><figcaption>нигоҳубини ва парвариши тасмаи тибр барои сабзӣ (вақла)</figcaption></figure>\n<h3>Оё тасмаи тибро метавон дар соли оянда боз истифода бурд?</h3>\n<p>Тасмаҳои полиетилен бо ғафсии баланд (0.4 миллиметр ва бештар) метавонанд, агар тозагии кофӣ ҳосил шавад, як ё ду фаввос (мавсим) дигар истифода шаванд. Аммо тасмаҳои нозук одатан дараҷаи баланде барои шикастан ва мокишидан доранд. Барои ошноӣ бо меъёрҳои нигоҳубинӣ, ба қисми ҳолатҳои обӣ-баробаришавӣ дар карбалоа, ки намунаҳои амалии нигоҳубини системаҳои сачадаро (қатрагинро) таъриф мекунад, диққат диҳед.</p>\n\n[ [ [ I M A G E _ 3 ] ] ]\n\n<h2>Хулоса: қадамҳои ниҳоӣ барои замин (меҳдор) солим</h2>\n<p>Нигоҳубини сабзӣ (вақла) бо тасмаи тибр, омезиши дониши техникӣ, назорати дақиқ ва барномагузорӣ аст. Аз интихоби масоҳаи муносиби тасма то идоракунии фишори об ва пешгирии хӯнидани нӯр, ҳар як ин омил ба сифати дони (дана) сабзии шумо таъсир мерасонад. Бо риояи асосҳо <strong>Муаллифи имингардидашуда (бо ҳимоя ҳифшуда)</strong> Дар ин мақола, шумат на танҳо ҳарҷавҳи обёрӣро паст намемузед, балки саломати оҳанг-ро низ нигоҳ медоред.</p>\n<p>Ду нуқтаи охирин барои пуррагии қисмҳои амалӣ:</p>\n<ol>\n<li><strong>Санҷиши бинӣ:</strong> Ҳар рӯз дар аввалин баробари обёрӣ, қисмҳоеро аз риштаи обёрӣ санҷед. Лутҳоеро, ки хӯрда шуда ё сӯрох доранд, дар ҳамон лаҳза барқарор кунед.</li>\n<li><strong>Мулоимати иқлим:</strong> Дар минтақаҳои хушк, барои пешгирии шидиди рутубати решаҳои сатҳӣ, аз риштаҳои нозуктар ва бодиҳиши баланди обӣ истифода баред, то риштаҳо нахунанд. Барои маълумот дар бораи мутобиқ кардани система бо иқлимҳои гуногун, аз дастурамали <a href="https://navar-abyari.ir/afzoyishi-hosili-pomidori-dar-gekter/" target="_blank">Зиёд кардани ҳосилоти помидор дар ҳектар</a> шумат метавонед илҳом гирифтед, зеро асосҳои физикии обёрии қатрагӣ барои ҳамаи намудиҳо якхела аст.</li>\n</ol>\n<p>Дар хотима, муваффақият дар парвариши боб бар системаи наварӣ ба сармоягузории дар ояндаи сабзтар ва боришкунанда аст. Бо риоя кардани нуқтаҳои зикршуда, шумо метавонед мҳсулоти баъи бетириро бо камтарин истифодабарии об истеҳсол кунед.</p>','Нигоҳубини бақала бо нвар Тейп: Нуқтаҳои асосӣ барои барориши ҳадди ақал','Дар ин мақола роҳнамои пурра барои нигоҳдории боб (бақала) бо системаи банди типӣ пешниҳод шудааст. Мо аз интихоби намуди мувофиқи банд то нуқтаҳои дақиқ дар бораи идоракунии фишори об ва пешгирии гузаштанҳои система бо тафсилот баррасӣ мекунем.','publish','closed','closed','nigohubini-baqala-bo-navar-afp',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
