INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Роҳҳои асосӣ барои зиёд кардани истеҳсоли лӯбиё дар ҳектар бо истифода аз технологияи нӯронкунии пуршавон (Drip) барои кишоварон. Дар осеини маводи баҳодиҳии тасмимию, тақсимоти адолатнок ва дидорои кӯдакон мавориди аҳмими ҷамъ шудаанд.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
