INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>أهمية تحديد كمية بذور الذرة في الهكتار بشكل صحيح</h2>\n<p>أحد أهم القرارات الحيوية في إدارة محصول الذرة هو اختيار متغير كمية بذور الذرة في الهكتار. هذه النسبة ليست ثابتة بل تتأثر بعوامل مثل تصنيف البذور (R1 حتى R5)، والمسافة بين الصفوف، والظروف المناخية للمناطق ونوع نظام الري. البذر الزائد عن الحد يسبب تنافسًا شديدًا بين النباتات على الضوء والعناصر الغذائية مما يؤدي إلى انخفاض حجم الحبوب واحتمال حدوث العقد، بينما البذر أقل من الحد المطلوب يسبب استغلالًا غير كافٍ لموارد الحقل وانخفاضًا في إجمالي الإنتاج.</p>\n<p>لأفضل فهم توازن بين الكثافة والإنتاجية، يُنصح بمقابلة المقال <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%B0%D8%B1%D8%AA-%D9%85%DA%A9%D8%B2%DB%8C%DA%A9%DB%8C-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">حجم محصول الذرة المتخصص في الهكتار</a> لحصولك على رؤية شاملة حول النتيجة النهائية.</p>\n\n<h2>معادلات حسابية لحساب كمية بذور الذرة في الهكتار</h2>\n<p>يتم حساب كمية بذور الذرة في الهكتار بناءً على متغيرين رئيسيين: المسافة بين الصفوف (بالمتر) والمسافة بين بذرتين في الصف الواحد (بالمتر). الرقم المرجعي العام لمناخ إيران هو زراعة من 55 إلى 60 ألف بذرة حية في الهكتار، لكن هذه الأرقام قد تختلف.</p>\n<h3>المرحلة الأولى: تحديد الكثافة المطلوبة في الصف</h3>\n<p>على فرض أن مسافة الصفوف ٧٥ سنتيمتراً (المعيار الشائع) ومسافة البذرتين ٢٥ سنتيمتراً، فإن الحسابات هي كما يلي:</p>\n\n<ul>\n<li>عدد البذور في كل متر من الصف: ١٠٠ سنتيمتر مقسوماً على مسافة البذرتين (٢٥ سنتيمتراً) يساوي ٤ بذور في المتر.</li>\n<li>عدد الصفوف في كل هكتار: يُنظر إلى حوالي ١٣٣ صفاً يتم وضعها في طول المزرعة (١٠٠ متر) من خلال قسمة عرض الأرض (١٠٠ متر) على مسافة الصفوف (٠.٧٥ متر).</li>\n<li>إجمالي عدد البذور في الهكتار: الطريقة التطبيقية هي ضرب ١٠٠ متر طول الصف في ٤ بذور لكل متر (لصّف واحد) ثم في عدد الصفوف الممكنة على المساحة (١٠٠ متر عرض مقسوماً على مسافة ٠.٧٥ متر). الحساب الدقيق: (١٠٠ متر / ٠.٧٥ متر) × ١٠٠ متر × ٤ بذور/متر ≈ ٥٣,٣٣٣ بذرة في الهكتار.</li>\n<li>إذا انخفضت مسافة البذور إلى ٢٠ سنتيمتراً، تزداد الكثافة إلى ٥ بذور لكل متر ويصل الرقم النهائي إلى حوالي ٦٦,٦٦٦ بذرة في الهكتار، وهو عدد كبير جداً لمعظم الأصناف.</li>\n</ul>\n<h3>تأثير تصنيف البذور على كمية البذور</h3>\n<p>تحتاج أنواع الذرة ذات التصنيف المنخفض (R1 و R2) عادةً إلى كثافة أقل (حوالي ٤٥-٥٠ ألفاً)، بينما تحتاج أنواع الذرة المتأخرة النضج (R4 و R5) إلى كثافة أعلى (حوالي ٥٥-٦٠ ألفاً). إذا كنت تستخدم بذوراً هجينة جديدة، راجع دائماً ملصق كيس البذور. الأصناف التي تتميز بإنتاج أكثر من ٢٠ أذن على الساق الرئيسية تتحمل كثافة أعلى للاستفادة من قدراتها النهائية.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-ذرت-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر ذرت در هکتار: راهنمای جامع - تصویر 1"/><figcaption>معدل البذر للهكتار لمحصول الذرة</figcaption></figure>\n\n<h2>الربط بين كمية بذار الذرة في الهكتار ونظم الري</h2>\n<p>نظم الري الحديثة مثل التنقيط ونظام الشريط المتقطع تؤثر بشكل مباشر على توزيع الجذور ونتيجة لذلك على متطلبات كثافة الزراعة. في نظم الري المطري، يؤدي توزيع الرطوبة المتجانس إلى أن تكون الزراعة بكثافة متوسطة قابلة للإدارة، ولكن في الري بالتنقيط، تتركز المياه حول النبات.</p>\n<h3>الري بالتنقيط وكثافة الزراعة</h3>\n<p>في الري بالتنقيط، يُوصى باستخدام كثافات أعلى (قريبة من الحد الأقصى المقصود، أي 60 ألف حبة). وذلك لأن منطقة التبليل ضيقة، ويجب أن توضع النباتات على مسافات أقصر من بعضها لتستفيد بأقصى قدر من المصادر الغذائية في منطقة الجذور. إذا كنت قد انتقلت حديثاً إلى نظام تنقيط جديد، فإن قراءة كيفية اختيار خط التنقيط المناسب ستساعدك على تنسيق المسافة بين نقطة التنقيط وصف الزراعة.</p>\n<h3>ري نظام الشريط المتقطع وزراعة الصف المجاور</h3>\n<p>في نظام الشريط المتقطع، يتم الري عبر شرائط منتظمة. إذا كنت تستخدم نظام الشريط المتقطع المتجاور (حيث يكون النبات ملاصقاً تماماً للشرط)، فيجب أن تعدّل بدقة أكبر في حسابات كمية بذار الذرة في الهكتار، والمسافة بين الحبوب والشرط وبين بعضها البعض، حتى لا تمنع النباتات الظل عن بعضها البعض ويصل ضوء كافٍ للحبوب السفلية. لفهم الفروق الهيكلية بين الأنظمة، يرجى قراءة مقال حول الفرق بين نظام الشريط المتقطع المتجاور والرقعي.</p>\n\n\n<h2>نصائح عملية لتحسين الزراعة وإدارة الحقل</h2>\n<p>الحراثة المناسبة، وتوفر الرطوبة الكافية للبذور قبل الزراعة، ومعايرة جهاز البذر، هي الركائز الثلاث الأساسية. إذا تم تجاهل أي منها، حتى أفضل الحسابات النظرية لن تكون ذات فائدة.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-ذرت-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر ذرت در هکتار: راهنمای جامع - تصویر 2"/><figcaption>معدل بذر لكل هكتار محصول الذرة</figcaption></figure>\n<ol>\n<li><strong>وزن مئة بذرة:</strong> لتحويل كمية البذور بالكيلوغرام إلى عدد الحبات، احسب وزن متوسط 100 حبة. مثال: إذا كان وزن 100 حبة 35 غراماً، فإن كل كيلوغرام يحتوي على 2857 حبة. لزراعة 55,000 حبة في الهكتار، تحتاج إلى حوالي 19.2 كيلوغراماً من البذور.</li>\n<li><strong>إدارة المنافسة:</strong> في الحقول ذات التربة الخفيفة والري بالتنقيط، قد تكون هناك حاجة إلى كثافة أعلى لتحقيق تغطية أسرع للغطاء النباتي وتقليل تبخر رطوبة سطح التربة. يساعد هذا في الحفاظ على الرطوبة لنمو البراعم.</li>\n<li><strong>تغيير مسافة الصفوف:</strong> إذا كان بإمكانك الزراعة بمسافة 80 إلى 90 سنتيمتراً (لأجهزة الحصاد الآلي)، فيجب زيادة المسافة بين الحبات في الصف حتى تبقى الكمية الإجمالية للهكتار ثابتة، أو العكس، تقليل مسافة الصفوف.</li>\n</ol>\n<p>كما أنه، من أجل مقارنة إنتاجية الذرة مع البقوليات والخضروات الأخرى، يساعد فهم متغيرات الكثافة في كل محصول على الاستخدام الأفضل لموارد البذور. يمكن أن يوفر دراسة كمية بذور البازلاء في الهكتار والعوامل المؤثرة رؤى أوسع لإدارة الكثافة في النظم المختلفة.</p>\n\n<h2>الأسئلة المتداولة (FAQ)</h2>\n<h3>هل يوجد مقدار ثابت لقيمة بذار الذرة في الهكتار؟</h3>\n<p>لا. يتراوح هذا المقدار بين ٤٥,٠٠٠ إلى ٦٥,٠٠٠ بذرة حية في الهكتار، ويعتمد على تصنيف البذور (EAR)، وطول موسم النمو، ونوع الري. أفضل معيار هو أقصى غطاء ظللي قبل مرحلة ١٢ ورقة.</p>\n<h3>هل يؤثر الري بالتنقيط على عدد الحبوب في الهكتار؟</h3>\n<p>نعم. في نظام الري بالتنقيط، بسبب تباين الرطوبة على طول الصف، يُوصى عادةً بتقليل الكثافة بنسبة حوالي ١٠٪ عن الأرقام المرجعية للتنقيط حتى لا تتضرر النباتات في نهاية الصنف.</p>\n\n<h3>كيف نمنع نقص بذور الأجساد؟</h3>\n<p>خذ دائماً نسبة إنبات البذور (Germination) بعين الاعتبار بناءً على ملصق العبوة. إذا كانت نسبة الإنبات ٩٠٪، يجب زراعة ١٠٪ من البذور الإضافية لضمان الكثافة النهائية المطلوبة في الحقل. يجب إجراء هذا الحساب قبل بدء الزراعة.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-ذرت-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر ذرت در هکتار: راهنمای جامع - تصویر 3"/><figcaption>معدل البذر لكل هكتار لمحصول الذرة</figcaption></figure>\n\n<h2>التحليل والتجربة</h2>\n<p>تحديد دقيق <strong>كمية بذور الذرة للهيكتار</strong> إنها عملية مركبة تشمل حسابات رياضية، ومعرفات بالمناخ، وفهمًا عميقًا لأنظمة الري (التنقيط أو شريط التيب). من خلال تنسيق مسافات الصفوف، وكثافة البذور في الصف، وإدارة الرطوبة، يمكن تحقيق أقصى كفاءة لاستخدام الأرض وزيادة إنتاج الحبوب. يُنصح في السنة الأولى من الزراعة بزراعة قسم تجريبي من الحقل بكثافتين مختلفتين (مثل 50,000 و60,000)، ثم مقارنة الغلة وجودة الحبوب في نهاية الموسم لتحديد المتغير المثالي لمزارعكم.</p>\n<p><strong>محتويات ذات صلة:</strong> كمية بذور الفول السوداني للهيكتار + العوامل المؤثرة، الفرق بين شريط تيب بحرف U وشريط تيب مسطح، كمية إنتاج الخس المحمر للهيكتار: العوامل المؤثرة + طريقة الزيادة، كمية إنتاج البازلاء الطازجة للهيكتار: دليل شامل والعوامل المؤثرة</p>\n<p><strong>محتويات ذات صلة:</strong> <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d9%86%d8%ae%d9%88%d8%af-%d9%81%d8%b1%d9%86%da%af%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">كمية بذور الفول السوداني للهيكتار + العوامل المؤثرة</a>, <a href="https://navar-abyari.ir/%d8%aa%d9%81%d8%a7%d9%88%d8%aa-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d8%a8%d8%ba%d9%84-%d8%af%d9%88%d8%ae%d8%aa-%d9%88-%d9%be%d9%84%d8%a7%da%a9%d8%af%d8%a7%d8%b1/">الفرق بين شريط الخياطة المتواصل والخياطة الدورية والمُرمّزة</a>, <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%da%a9%d8%a7%d9%87%d9%88-%d9%be%db%8c%da%86-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">معدل حصاد الخس الحلزوني في الهكتار: العوامل المؤثرة + طريقة الزيادة</a></p>','كمية بذور الذرة في الهكتار: دليل شامل للزراعة وإدارة الري','التحديد الدقيق لكمية بذور الذرة لكل هكتار يتطلب معرفة تصنيف البذور والمسافة بين الصفوف وطرق الزراعة. في هذا المقال، نراجع المعادلات الحسابية والنقاط العملية لزراعة الذرة بنظام الري بالتنقيط والنقاط التيب، وذلك لتحقيق الكثافة المثالية والرفع من المحصول.','publish','closed','closed','quantity-of-corn-seed-per-hectar-irrigation-guide',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
