INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Аҳамияти муайян кардани дурусти миқдори бӯи ҷӯр дар гектар</h2>\n<p>Яке аз муҳимтарин қарорҳо дар идоракунии саҳрои ҷӯр ин интихоби тағйирёбандаи «миқдори бӯи ҷӯр дар гектар» аст. Ин рақам доимӣ нест ва зери таъсири омилҳое чун гуномкунии бӯ (R1 то R5), масофаи байни сатрҳо, шароити иқлимии минтақа ва намуди системаи оборӣ қарор дорад. Нишон доҳидани зиёд ба рақобати шадиди рӯяниҳо барои нуқш ва моддаҳои ғизоӣ ва дар натиҷаи он ба камшавии андозаи дон ва эҳтимоли шӯр шудан оварда мерасонад, дар ҳоле ки нишон доҳидани камтар аз ҳадди марӯб ба истифодаи нокифи аз манбаъҳои саҳро ва камшавии истеҳсоли умумӣ мусоидат мекунад.</p>\n<p>Барои фаҳмиши беҳтари мувозинат байни зичӣ ва истеҳсолат, тавсия дода мешавад, ки ба мақола <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%B0%D8%B1%D8%AA-%D9%85%DA%A9%D8%B2%DB%8C%DA%A9%DB%8C-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Миқдори ҷамъоварии ҷӯр дар як гектар</a> намояд, то назари васеътарро дар бораи натиҷаи ниҳоӣ дошта бошед.</p>\n\n<h2>Формулаҳои ҳисоббарӣ барои ҳисоб кардани дон дар гектар</h2>\n<p>Ҳисоб кардани миқдори бӯи ҷӯр дар гектар дар асоси ду тағйирёбандаи асосӣ сурат меёбад: масофаи байни сатрҳо (ба метр) ва масофаи байни ду дон дар як сатр (ба сентиметр). Рақами референси умумӣ барои иқлими Ҷумҳурии Эрон, нишон доҳидани 55 то 60 ҳазор дони зинда дар гектар аст, аммо ин рақамҳо метавонанд тағйирёбанда бошанд.</p>\n<h3>Марҳилаи якум: муайян кардани зичии марӯб дар сатр</h3>\n<p>Бо фарзиядани масофаи 75 сантиметр байни сатҳҳо (стандарди маъруф) ва масофаи 25 сантиметр байни ду тохур, ҳисобҳо чунин мебошад:</p>\n\n<ul>\n<li>Шумораи тохур дар ҳар метр сатҳ: 100 сантиметр тақсим бар масофаи ду тохур (25 сантиметр) баробар ба 4 тохур дар метр аст.</li>\n<li>Шумораи сатҳҳо дар ҳар гектар: андозаи замин (100 метр) тақсим бар масофаи сатҳ (0.75 метр) тақрибан 133 сатҳ дар назар гирифта мешавад, ки дар тӯли мазре (100 метр) ҷойгир мешаванд.</li>\n<li>Шумораи умумии тохур дар гектар: Усули амалӣ ин аст, ки 100 метри тӯли сатҳро ба 4 тохур дар метр (барои як сатҳ) ва сипас ба шумораи имконпазири сатҳҳо аз сатҳ (андозаи 100 метр тақсим бар масофаи 0.75 метр) зарб занем. Ҳисобҳои дақиқ: (100 метр / 0.75 метр) × 100 метр × 4 тохур/метр ≈ 53,333 тохур дар гектар.</li>\n<li>Агар масофаи тохурҳо то 20 сантиметр расад, зичӣ ба 5 тохур дар метр зиёд мешавад ва рақами ниҳоӣ ба тақрибан 66,666 тохур дар гектар мерасад, ки барои аксари навъҳо хеле зиёд аст.</li>\n</ul>\n<h3>Таъсири зиндагирӣ боздани бар миқдори бозда</h3>\n<p>Шукри бо зиндагирии пасттар (R1 ва R2) одатан ба зичии камтар (тақрибан 45-50 ҳазор) ниёз доранд ва шукри дерпаканда (R4 ва R5) ба зичии бештар (тақрибан 55-60 ҳазор). Агар шумо боздаҳои навку гибридӣ истифода мебаред, ҳатман ба лабелки бозда нигоҳ кунед. Навъҳое, ки бо дар асоси 20 тохур ва зиёдтар дар сабури асосӣ ҳастанд, зичии баландтарро давоҳм мекунанд, то аз имкониятҳои ниҳоии худ истифода барояд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-ذرت-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر ذرت در هکتار: راهنمای جامع - تصویر 1"/><figcaption>миқдори бозда дар гектар зери куштани шукр</figcaption></figure>\n\n<h2>Таълиқ миқдори бехи гӯгма дар ҳектар бо системаҳои обёрӣ</h2>\n<p>Системаҳои навии обёрӣ, ба монанди қаъқуқорӣ (дрилӣ) ва пастаҳо, бевосита ба тақсимоти ризоҳо ва дар натиҷа ба ниёз ба зичии бехбарӣ таъсир мерасонанд. Дар системаҳои ёморӣ (баронӣ), тақсимоти якхелаи намнокӣ имконро медиҳад, ки бехбарӣ бо зичии миёна идора карда шавад, аммо дар обёрии қаъқуқорӣ (дрилӣ), об дар атрофи растани мутмаззид мешавад.</p>\n<h3>Обёрии қаъқуқорӣ (дрилӣ) ва зичии бехбарӣ</h3>\n<p>Дар обёрии қаъқуқуқорӣ (дрилӣ), тавсия карда мешавад, ки аз зичии баландтар (ба ҳадди имкон, масалан 60 ҳазор бех) истифода шавад. Зеро доираи намнокшуда танг аст ва растаниҳо бояд дар фосилаҳои кӯтоҳтар аз ҳам ҷойгир шаванд, то аз манбаъҳои ғизоии маҳдуди минтақаи ризоҳо фоидаи максималӣ истифода кунанд. Агар шумо ба системаи нави қаъқуқорӣ (дрилӣ) муроҷиат карда бошед, омӯзиши тарзи интихоби пастаи мувофиқи обёрии қаъқуқорӣ (дрилӣ) барои мувофиқкунии фосилаи сарчашма (нормал) бо сафи бехбарӣ кӯмакрасан аст.</p>\n<h3>Обёрии пастаҳо (банд) ва бехбарӣ дар ҷиҳати пастаҳо</h3>\n<p>Дар системаи пастаҳо (банд), обёрӣ аз рӯи пастаҳои нозук сурат мегирад. Агар аз системаи пастаҳои нозук дар ҷиҳати пастаҳо истифода кунед ҷое, ки растани тамамо қари паста ҷойгир аст, бояд дар ҳисобҳои миқдори бехи гӯгма дар ҳектар, фосилаи бехҳо аз паста ва аз ҳамроҳро дақиқтар танзим кунед, то ки дар соянифшудани растаниҳо ба ҳамдигар, рӯшнои кофӣ ба бехҳои поёнӣ расад. Барои фаҳмиши фарқиятҳои сохтории системаҳо, мақолаи "Фарқи пастаи нозук дар ҷиҳати пастаҳо ва пастаи пук (плъядар)"-ро омӯзед.</p>\n\n\n<h2>Нуқтаҳои амалӣ барои беҳтар кардани бехбарӣ ва идоракунии замин</h2>\n<p>Бурри мувофиқ барои бехбарӣ, намноки кофии бехҳо пеш аз бехбарӣ ва калибратсияи коркардкунанда, се асоси асосӣ ҳастанд, ки агар диққат надид шавад, ҳатто беҳтарин ҳисобҳои назарӣ номуътадил мешаванд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-ذرت-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر ذرت در هکتار: راهنمای جامع - تصویر 2"/><figcaption>миқдори ғаллод ба ҳазор метр мураббаъ барои ғаллод Зағор</figcaption></figure>\n<ol>\n<li><strong>Синози вазни 100 дона ғаллод:</strong> Барои табдил додани миқдори ғаллод аз килограмм ба шумораи дона, вазни миёнаи 100 донаро муайян кунед. Масалан: агар вазни 100 дона 35 грамм бошад, дар як килограмм 2857 дона ҳаст. Барои кордани 55,000 дона дар як гектар, тақрибан 19.2 килограмм ғаллод лозим аст.</li>\n<li><strong>Мудоирати рақобат:</strong> Дар майдонҳои ки замини сабук ва ошориқубаро доранд, метавонад лозимат ба зичии баландтар бошад, то сарпӯши бодоргон тезтар ба амал орад ва буҳоршавии замини поён коҳиш ёбад. Ин кор барои нигоҳ доштани намӣ барои рӯиш пайдои гулчаҳо кӯмак мекунад.</li>\n<li><strong>Тағйири фосилаи сатҳҳо:</strong> Агар имкони кордон бо фосилаи 80 то 90 сантиметрро дошта бошед (барои асбобҳои ҷамъоварии механикавӣ), бояд фосилаи донаҳо дар сатҳро зиёд кунед, то шумораи умумӣ дар як гектар собит бошад ё баръакс, фосилаи сатҳҳоро камтар кунед.</li>\n</ol>\n<p>Бинобар ин, барои муқоиса кардани самаранокии ғаллод бо дигар ғаллоду сабзавот, фаҳмиши тағйирёбандаҳои зичӣ дар ҳар як маҳсул кӯмак мекунад, то ба истифодаи беҳтари захираҳои ғаллод даст ёбед. омӯзиши миқдори ғаллоди нуқушдори хӯрокӣ дар як гектар + омили таъсиррасон метавонад нигарониши васеътарро нисбат ба мудоирати зичӣ дар системаҳои чандқабата ба вуҷуд орад.</p>\n\n<h2>Саволҳои маъмул (FAQ)</h2>\n<h3>Оё миқдори муайяни барои ғанҷи буби гудо дар ҷаво вуҷуд дорад?</h3>\n<p>Не. Ин миқдор аз 45,000 то 65,000 дони зинда дар ҷаво тағйир меёбад ва ба гурӯҳи буби (EAR), дарозии давраи афрӯиш ва намуди ороиш вобаста аст. Беҳтарин миқос, бештарин пӯшиши нисбат ба марҳалаи 12 барг аст.</p>\n<h3>Оё ороиши навъи тасеъ ба шумораи донҳо дар ҷаво таъсир мерасонад?</h3>\n<p>Бале. Дар системаи тасеъ, ба сабаби тағйирёбии намнокӣ дар тӯли қатор, одатан тавсия мешавад, ки зичро тақрибан 10% камтар аз рақамҳои иқобати бораҳо ба назар гиред, то ғазоби расмҳо дар охири навъро пешгирӣ кунед.</p>\n\n<h3>Чӣ гуна аз камбудии буби физикӣ пешгирӣ мекунем?</h3>\n<p>Ҳамیشа фоизи афрӯиши буби (Germination)-ро бар асоси намоиши баста ба назар гиред. Агар фоизи афрӯиш 90% бошад, бояд 10% буби иловагӣ кашед, то зичии ниҳоии мурожӣ дар замин таъмин шавад. Ин ҳисобкунӣ бояд пеш аз оғоzi корти кортиш анҷом дода шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-ذرت-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر ذرت در هکتار: راهنمای جامع - تصویر 3"/><figcaption>seed rate per hectare crop гудо</figcaption></figure>\n\n<h2>Хулоса</h2>\n<p>Муайяни дақиқ <strong>Микдори бехи боқалову дар як гектар</strong> Ин раванди омехта аст, ки ҳисобҳои риёзӣ, шиносоии иқлим ва фаҳмиши амиқро аз системаи оборӣ (қатрӣ ё навори дрилл) дар бар мегирад. Тавассути мувофиқ кардани фосилаи байни сатҳҳо, зичии бех дар сатҳ ва идоракунии рағори об метавон ба ҳадди аксар самаранокии замин ва зиёд шудани ҳосили дона расид. Маслиҳат дода мешавад, ки дар соли аввали эк, як қисми таҷрибии роғатро бо ду зичии гуногун (масалан, 50 ҳазор ва 60 ҳазор) екунед ва дар охири фасл ҳосил ва сифати донаро муқоиса кунед, то тағйирёбандаи мувофиқро барои роғатҳои худ муайян кунед.</p>\n<p><strong>Мавзӯҳои алоқаманд:</strong> Микдори бехи бӯкӯ дар як гектар + омилҳои таъсирангиз, фарқияти навори дрилл дар ҷанбаи қатор ва ҷойҷой, ҳаҷми ҳосили сабзӣ-калӣ дар як гектар: омилҳои таъсирангиз + усули зиёд кардан, ҳаҷми ҳосили чангӯ дар як гектар: дастурашиносии мукаммал ва омилҳои таъсирангиз</p>\n<p><strong>Мавзӯҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d9%86%d8%ae%d9%88%d8%af-%d9%81%d8%b1%d9%86%da%af%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Микдори бехи бӯкӯ дар як гектар + омилҳои таъсирангиз</a>, <a href="https://navar-abyari.ir/%d8%aa%d9%81%d8%a7%d9%88%d8%aa-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d8%a8%d8%ba%d9%84-%d8%af%d9%88%d8%ae%d8%aa-%d9%88-%d9%be%d9%84%d8%a7%da%a9%d8%af%d8%a7%d8%b1/">Фарқияти тасмаи чӯб (tip) бо дӯзист ва таваққуфӣ</a>, <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%da%a9%d8%a7%d9%87%d9%88-%d9%be%db%8c%da%86-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми ғалами лаҳҷаи бодирка дар ҳектар: омили таъсир + роҳи зиёдкунӣ</a></p>','Ҳаҷми бодираи ҷавдорӣ ба ҳектар: Равонамои ҷамъбасти бодириш ва идоракунии ободӣ','Муайян кардани мувофиқи миқдори боби корнбоқалар дар ҳектар ба ошноӣ бо дараҷаи боби, масофаи шӯрбаҳо ва усулҳои партоб вобаста аст. Дар ин мақола, формулаҳои ҳисобӣ ва нокиҳоҳои амалӣ барои партоби қаторӣ бо обкорӣ ва тасмашаклро баррасӣ мекунем, то ки чигилии ҳадди сатҳ ва истеҳсолоти баландро кӯлиш кунед.','publish','closed','closed','hajmi-bodirai-chandori-ba-hektar-rahnamoyi-bodirish-obodi',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
