INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='tj' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>المقدمة: أهمية دقة تحديد كثافة زراعة الكولز</h2>\n<p>الكولز من أهم محاصيل الزيوت في البذار الخريفي والربيعي، ويتم زراعتها في العديد من المناخات في إيران. ومن أكثر الأسئلة شيوعًا لدى المزارعين حول هذه المحصول، <strong>كمية بذور الكولز في الهكتار الواحد</strong> . تحديد هذه القيمة بدقة يؤثر بشكل مباشر على تغطية التربة، والمنافسة مع الأعشاب الضارة، واستهلاك الماء، والمحصلة النهائية. في الزراعة الحديثة التي تستخدم أنظمة الري بالتنقيط والخطوط، يكون التوازن بين كثافة الأدغال وشدة الري أكثر حساسية مما هو عليه في الزراعة التقليدية. إذا كانت الكثافة عالية جدًا، تتنافس النباتات على الماء والعناصر الغذائية وتكون الجذور ضعيفة؛ لكن إذا كانت الكثافة منخفضة، لا يُستغل كامل إنتاج الزيت في كل نبات، وتتاح الفرصة للأعشاب الضارة للنمو.</p>\n<p>الهدف من هذا الدليل هو تقديم رؤية عملية قائمة على البيانات العلمية، بحيث يتمكن المزارع من اختيار النقطة المثلى، من حد 25 كغم إلى 45 كغم من البذور في الهكتار الواحد، بناءً على ظروف حقوله.</p>\n\n\n\n<h2>العوامل الحاسمة في تحديد كمية بذور الكولز في الهكتار</h2>\n<p>لا توجد قيمة ثابتة مطلقة تناسب جميع الحقول. كمية بذور الكولز في الهكتار تتغير حسب المتغيرات التالية:</p>\n<ul>\n<li><strong>الأصناف النباتية:</strong> تفاوت جذري بين ارقام متوسّط في حجم البذرة (مثل 20-25 ألف بذرة لكل هكتار) والارقام العملاقة (5-8 آلاف بذرة لكل هكتار) واضحة. عادةً ما تكون الأرقام الحديثة أرقاماً شبه عملاقة تحتاج إلى كثافة زراعية متوسطة.</li>\n<li><strong>رطوبة التربة ووضع الريّ:</strong> في المناطق التي تعتمد على الري بالتنقيط حيث يحدث نمو الجذور بشكل أسرع، يمكن استخدام كثافة أعلى قليلاً. بالمقابل، في الزراعة المطرية أو مع أنظمة تنقيط غير مستقرة، فإن الكثافة المنخفضة تقلل من المخاطر.</li>\n<li><strong>أهم عامل:</strong> قابلية إنبات البذرة. البذور الطازجة ذات قابلية إنبات تتجاوز 95٪ تتطلب كمية بذور أقل مقارنةً بالبذور القديمة ذات قابلية إنبات 80٪ لكل وحدة مساحة.</li>\n</ul>\n<p>لفهم أفضل لكيفية حساب الكثافة وأثرها على إدارة الموارد، يمكن دراسة موضوع معدل محصول الذرة (الحبوب) للهكتار الذي يقدم رؤية مماثلة لتوازن كثافة النباتات والمدخلات، لأن المنطق الفسيولوجي للنباتات في المحاصيل الحبوبية متشابه.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-گلرنگ-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر گلرنگ در هکتار: راهنمای جامع - تصویر 1"/><figcaption>معدل البذرة للهكتار محاصيل الذرة المحبوبة</figcaption></figure>\n\n<h2>جدول مقارنة كثافة الزراعة حسب الظروف</h2>\n<p>الجدول التالي هو فهرس للنطاقات الموصى بها عموماً لـ <strong>معدل بذر الحنطة العاشر للفدان الواحد</strong> وفقاً للنوع وطريقة الزراعة:</p>\n<table border="1" style="border-collapse: collapse; width: 100%;">\n<thead>\n<tr>\n<th>ظروف الزراعة</th>\n<th>نوع السلالة</th>\n<th>حد الكثافة (نبات/هكتار)</th>\n<th>المقدار التقريبي للبذور (كغم/هكتار)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>الري بالرش والري بالتنقيط الكامل</td>\n<td>موسمي</td>\n<td>٥٠٬٠٠٠ - ٦٠٬٠٠٠</td>\n<td>٢٥ - ٣٠</td>\n</tr>\n<tr>\n<td>نصفي صحراوي / شحيحة الماء</td>\n<td>موسمي</td>\n<td>٤٠٬٠٠٠ - ٥٠٬٠٠٠</td>\n<td>٢٠ - ٢٥</td>\n</tr>\n<tr>\n<td>قارّي بري</td>\n<td>نصف عملاق</td>\n<td>70,000 - 85,000</td>\n<td>35 - 45</td>\n</tr>\n<tr>\n<td>شبه صحراوي / شحيحة المياه</td>\n<td>نصف عملاق</td>\n<td>60,000 - 70,000</td>\n<td>30 - 35</td>\n</tr>\n</tbody>\n</table>\n<p>يُذكر أن تقدير البذر تم على فرض وزن الألف حبة 400 إلى 550 غرام. إذا استخدمت أصنافاً أخف، فإن كمية البذر بالكيلوغرام لنفس عدد المراكز تتناقص.</p>\n\n\n\n<h2>التآزر بين معدل البذر والري بالتنقيط</h2>\n<p>يتيح نظام الري بالتنقيط، بسبب توزيع الأدق للمياه في منطقة الجذور وتقليل التبخر من سطح التربة، للمزارع استغلال إمكانات الأصناف عالية الغلة من القمح الحقل. في المناطق التي يكون فيها زرع القمح الحقل محفوفاً بالمخاطر بسبب ندرة المياه، يعد هذا النظام حيوياً. إدارة الري بالتنقيط تعني أنه يجب تكييف تناوب المحاصيل الدقيق مع فواصل الأشرطة لضمان عدم جفاف الشريط الأوسط بين كل قطارة وأخرى.</p>\n<p>بشكل خاص، إذا قمت بزيادة معدل بذور القمح الحقل لكل هكتار، تزداد كثافة فراش الجذور وترتفع كمية المياه المطلوبة في الساعات الأولى من النمو. في مثل هذه الظروف، يمكن أن يسمح استخدام قطارات بفاصل أقصر (مثلاً 20 سنتيمتر بدلاً من 40 سنتيمتر) بوصول معدل الإجهاد المائي بشكل كافٍ إلى المناطق ذات الكثافة العالية. لمعرفة مبادئ التركيب والصيانة الصحيحة لهذا النظام، مقال "مخطط الري بالتنقيط المناخي المحلي" دليل جيد لتكييف المعدات مع ظروف مزرعتك.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-گلرنگ-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر گلرنگ در هکتار: راهنمای جامع - تصویر 2"/><figcaption>معدل البذر للهكتار محصول القمح الحقل</figcaption></figure>\n\n<h3>تأثير الزرع في شرائط بعرض 20 و40</h3>\n<p>تؤثر فواصل الزراعة أيضاً على الحاجة إلى البذور. في الزراعة أحادية الصف، يعتمد كثافة الشتات للمتر المربع مباشرة على فاصلة الصفوف. إذا كانت الفاصلة بين الصفوف 20 سنتيمتراً، يزداد كثافة الشتات ويجب تقليل معدل بذور القمح الحقل لكل هكتار قدر الإمكان لتجنب المنافسة الشديدة بين الشتات التي تؤدي إلى إنتاج حبات أصغر حجماً. في المقابل، يخلق الزرع المزدوج أو في صفوف بعرض 40 سنتيمتراً مساحة أكبر لتطوير الشتات ويسمح بضبط الكثافة لتكون أعلى قليلاً (بافتراض أن حيوية البذور مناسبة).</p>\n\n\n\n<h2>نقاط عملية لزراعة بذور القمح الحقل</h2>\n<ol>\n<li><strong>البذر المنتظم:</strong> استخدم کنی زید زارع بیدرستی دقتهی تنظیم شده باشه. گم کردن یک‌سوم زرار از عمق نادرسته کارلایندگی ظاهری رو کاهش میده و حس میشه مقدار زرار کافیه نییسته. عمق زار ۳ تا ۵ سانتی‌متر ایدئاله.</li>\n<li><strong>استفاده ز زرار آکنده‌ساز:</strong> در بچش رقم‌ها، زرار آکنده‌ساز (پوش‌دار) حجم بیشیره شامل میشه. اگه از این نوع استفاده کنی، مقدار کیلوگرامی رو تا ۱۵ درصد زیاد کن.</li>\n<li><strong>آب دهی زرار اولیه:</strong> بلافاصله بعد از زارن و قبل از زارپاشی نهایی، یک نوار آب سبک اجرا کن تا زرار بره عمق رطوبت.</li>\n<li><strong>هم‌زمانی با آب دهی:</strong> با کاهش شدت آب قطره‌ای در شروع دوره رشد (جهت کنترل علف‌های هرز)، اگه از مقدار زرار گل‌رنگ در هکتار کمتر (نحوه ۲۵-۳۰ کیلو) استفاده کنی، باید از علف‌کش‌های پیش از لانه‌گزینی استفاده کنی.</li>\n</ol>\n\n<h2>سؤالات رایج (FAQ)</h2>\n<p><strong>1. هل يؤثر تغيير كمية بذر الكتان في الهكتار على جودة الزيت؟</strong><br>في الحالة القياسية، لا يوجد تأثير مباشر على نسبة الزيت، لكن يوجد تأثير على إجمالي إنتاج الزيت لكل هكتار (الكمية النهائية). عادةً، يؤدي التركز العالي إلى حبوب أصغر وأضعف، مما يقلل من كفاءة استخلاص الزيت في مصانع الحبوب.</p>\n<p><strong>2. هل تغير كمية البذور في المناطق الجبلية ذات الارتفاع العالي؟</strong><br>نعم. بسبب انخفاض درجة الحرارة والنمو الأبطأ، هناك حاجة إلى أصناف أقصر وسرعة نضج أعلى، والتي عادةً تتطلب تركزًا أعلى لضمان تغطية التربة بشكل كافٍ.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-گلرنگ-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر گلرنگ در هکتار: راهنمای جامع - تصویر 3"/><figcaption>معدل بذور الكتان في الهكتار</figcaption></figure>\n<p><strong>3. نظام الري بالتنقيط قديم، كم كمية البذور التي يجب أن أستخدمها؟</strong><br>في الأنظمة القديمة التي لا يكون فيها توزيع الماء موحدًا، استخدم الحد الأدنى من كمية البذور (حوالي 25-30 كيلوغرامًا للأصناف الطويلة). الحبوب في المناطق الجافة داخل الصفوف ستضعف عند استخدام تركز عالي.</p>\n\n<h2>الخلاصة</h2>\n<p>الاختيار <strong>كمية بذور الغرينغ في الهكتار</strong> قرار متعدد الأبعاد يشمل تركيب الأصناف وحالة الري وظروف المزرعة. بشكل عام، النطاق الآمن لمعظم الأصناف في إيران هو 25 إلى 45 كيلوغرام. إذا كنت تستخدم أنظمة الري الحديثة بالتنقيط والشريط التريبي، يمكنك التحرك نحو الأصناف نصف العملاقة بكثافة أعلى لزيادة قدرة إنتاج الزيت. استخدم دائمًا بذورًا نشطة ذات نسبة إنبات عالية حتى يتطابق عدد البذور المندفعة فعليًا مع عدد البذور المزروعة. للاطلاع على العوامل المؤثرة على إنتاج المحاصيل الأخرى ذات الكثافات المتغيرة، يمكنك قراءة مقال نقاط مهمة عند استخدام الشريط التريبي للري ومقال <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%aa%d9%88%d8%aa-%d9%81%d8%b1%d9%86%da%af%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">مستوى إنتاج الفراولة في الهكتار: عوامل وطرق التزايد</a> إقرائه.</p>\n<p><strong>مقالات ذات صلة:</strong> <a href="https://navar-abyari.ir/%D9%87%D8%B2%DB%8C%D9%86%D9%87-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%A8%D8%B1%D8%A7%DB%8C-%DB%8C%DA%A9-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1-%DA%86%D9%82%D8%AF%D8%B1-%D8%A7%D8%B3%D8%AA/">D987D8B2DB8CD986D987 D986D988D8A7D8B1 D8AADB8CD9BE D8A8D8B1D8A7DB8C DB8CDAA9 D987DAA9D8AAD8A7D8B1 DA86D982D8AFD8B1 D8A7D8B3D8AA</a>، <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%ae%d8%b1%d8%a8%d8%b2%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">كمية بذور القثاء في الهكتار + جدول كثافة الزراعة</a>، <a href="https://navar-abyari.ir/pakhtahosil-yeki-gektar-rahnama-kishovarzon/">pakhtahosil yeki gektar rahnama kishovarzon</a></p>','قِدر بذور گلرنگ در هکتار: دليل شامل للمزارعين العراقيين','في هذا الدليل، ستتعرف على العوامل المحددة لكمية بذور جُلُرَنغ لكل هكتار، والفرق بين الأصناف، وشروط الري بالتنقيط، لضمان زراعة مثالية وتقليل هدر الموارد.','publish','closed','closed','gloran-sowing-rate-per-hectare-guide-iraq',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
