INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Муҳимияти дақиқ будани зичии ниқди ҷуғҷӯғ (рапс)</h2>\n<p>Ҷуғҷӯғ (рапс) яке аз ҳолудорҳои асосӣ дар кишти тирамоҳӣ ва баҳорӣ аст, ки дар бисёр иқлими Эрон партоб дода мешавад. яке аз саволҳои маъмултарини кишоварзон дар бораи ин маҳсулот <strong>миқдори бӯнои ҷуғҷӯғ дар ҳектар</strong> аст. Муайян кардани дақиқи ин шумора бевосита ба пӯшиши хок, рақобат бо аʼсор, истеъмоли об ва дар натиҷа ҳаҷми ҳосили ниҳоӣ таъсир мерасонад. Дар киштҳои муосир, ки аз системаҳои обёрӣи тамғагӣ ва полосавӣ истифода мебаранд, ҳаммуофӣ байни зичии навиштҳо ва шиддати обёрӣ ҳатто ҳассосиаш аз киштҳои анъанавӣ аст. Агар зичӣ зиёда аз ҳад бошад, гиёҳҳо барои гирифтани об ва моддаҳои ғизоӣ рақобат мекунанд ва сохтори решаи заиф доранд; вале агар зичӣ кам бошад, қобилияти истеҳсоли ҳомили ҳар навишт ба таври пурра фаъол намешавад ва аʼсор фурсати афзоиш пайдо мекунанд.</p>\n<p>Мақсади ин роҳнам, пешниҳоди дидеки амалӣ ва асосгирифта ба донишҳои илмӣ мебошад, то ки кишоварз тавонад бар асоси шароити саҳнаи худ, аз ҳудуди 25 килограмм то 45 килограмм бӯно дар ҳектар, нуқтаи оптималиро интихоб кунад.</p>\n\n\n\n<h2>Амилҳои муайянкунандаи миқдори бӯнои ҷуғҷӯғ дар ҳектар</h2>\n<p>Ҳеҷ шумораи собит ва мутлақ барои ҳамаи саҳнаҳо вуҷуд надорад. Миқдори бӯнои ҷуғҷӯғ дар ҳектар ба ометабарҳои зерин вобаста аст:</p>\n<ul>\n<li><strong>Насабҳои растании:</strong> Нарядоҳои гулранг бо зарракаш (масалан, зарра 20-25 ҳазор дар ҳазор метр) фарқияти асосӣ доранд ба нарядои бузург (зарра 5-8 ҳазор дар ҳазор метр). Нарядҳои муосир одатан нарядҳои ним-бузурганд, ки ба зичии миёна ниёз доранд.</li>\n<li><strong>Рутубати хок ва вазъияти обкорӣ:</strong> Дар минтақаҳое, ки обкории баққабарӣ доранд ва решагузинии тезтар рух медиҳад, метавон аз зичии каме баландтар истифода бурд. Дар ҳолати эҳсои хушкзор ё баққабарии ноустувор, зичии поёнтар хатари камтар дорад.</li>\n<li><strong>Омил муҳимтарин:</strong> Фаъолияти зарра. Зарраҳои нав бо фаъолияти боло аз 95% ба томири камтар нисбат ба зарраҳои кӯҳна бо фаъолияти 80% дар як воҳиди масоҳат ниёз доранд.</li>\n</ul>\n<p>Барои фаҳмиши беҳтари роҳи ҳисоб кардани зичӣ ва таъсири он ба идоракунии захираҳо, омӯзиши мавзӯи миқдори ҳосили ҷӯ (ҷӯ-дана) дар ҳектар метавонад диди монанди таносуби зичии бутуна ва моддаҳои тарроҳӣ пешниҳод кунад, зеро логикии анатомияи бутун дар партозиши дарамонанда монанд аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-گلرنگ-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر گلرنگ در هکتار: راهنمای جامع - تصویر 1"/><figcaption>seed rate per hectare crop гулранг</figcaption></figure>\n\n<h2>Ҷадвали муқоисаии зичии нишон бо истифода аз шартҳо</h2>\n<p>Дар оварда ба хусуси ати хосусияти хосусияти хосусиятҳои оддӣ барои <strong>Миради дидони чӯкӣ дар ҳектар</strong> Асоси афзоиш ва усули кариш:</p>\n<table border="1" style="border-collapse: collapse; width: 100%;">\n<thead>\n<tr>\n<th>Шароити кариш</th>\n<th>Намунаи нав</th>\n<th>Маҳдуди зичӣ (ҳабҳо/ҳектар)</th>\n<th>Миради дастрас (кило/ҳектар)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Қатораи бӯстонӣ бо қатори намоишӣ</td>\n<td>Калонбадбод</td>\n<td>50 000 - 60 000</td>\n<td>25 - 30</td>\n</tr>\n<tr>\n<td>Нимбозорӣ / камобӣ</td>\n<td>Калонбадбод</td>\n<td>40 000 - 50 000</td>\n<td>20 - 25</td>\n</tr>\n<tr>\n<td>Қарачи бо таҷҳизоти қатраи пурра</td>\n<td>Нимагилл</td>\n<td>70,000 - 85,000</td>\n<td>35 - 45</td>\n</tr>\n<tr>\n<td>Нимекуҳистонӣ / камобии об</td>\n<td>Нимагилл</td>\n<td>60,000 - 70,000</td>\n<td>30 - 35</td>\n</tr>\n</tbody>\n</table>\n<p>Диққат дида шавад, ки ҳисоби миқдори бӯғӣ дар асоси вазни ҳазор дона аз 400 то 550 грамм анҷом шудааст. Агар аз намудҳои сабукиштар истифода баред, миқдори бӯғӣ дар килограм барои ҳамон шумораи бӯғӣ кам мешавад.</p>\n\n\n\n<h2>Ҳамкории миқдори боб ва оборию таррӣ</h2>\n<p>Системаи оборию таррӣ, аз сабаби тақсимоти дақиқтари об дар минтақаи решаҳо ва кам шудани бухоршавӣ аз сатҳи хок, имконро ба деҳқон медиҳад аз потенсиали намҳои бошорабарии бубӯри истифода барад. Дар минтаҳое, ки аз сабаби камии об, парвариши бубӯр хатарнок аст, ин система ҳаётӣ аст. Идоракунии таррӣ ба ин маъно аст, ки бояд таваққуфоти дақиқи каророниро бо фосилаҳои таррҳо танзим кард, то аз хушкшавии тарри миёна байни ду обгир пешгирӣ карда шавад.</p>\n<p>Баҳосиле агар миқдори бобро дар ҳектари бубӯр зиёд кунед, зичии пусти решаҳо баланд мешавад ва миқдори оби лозима дар соатҳои аввали рушд зиёд мешавад. Дар ин шартҳо, истифода аз обгирони бо фосилаи кам (масалан, фосилаи 20 сантиметр ба ҷои 40 сантиметр) метавонад суръати ниҳоро дар қисмҳои пур зиёд ба мақсад расонад. Барои шинос шудан бо асосҳои насб ва нигоҳубини дурусти ин система, мақолаи нақшаи тарри иқлими маҳаллӣ роҳнамои хуб барои мутобиқсозии асбобҳо бо шартҳои моли шумост.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-گلرنگ-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر گلرنگ در هکتار: راهنمای جامع - تصویر 2"/><figcaption>суръати боб дар ҳектари бубӯр</figcaption></figure>\n\n<h3>Таъсири карш дар таррҳои 20 ва 40</h3>\n<p>Фосилаҳои карш низ ба ниёз аз боб таъсир мерасонад. Дар карши якдони, зичии ноб дар метри мураба ба таври мустақим ба фосилаи пайҳаҳо вобаста аст. Агар фосила байни пайҳаҳо 20 сантиметр бошад, зичии ноб баланд мешавад ва бояд миқдори бобро дар ҳектари бубӯр чун қобилист кам кард, то аз рақобати шиддат мутаомад бобҳо, ки боиси истеҳсоли ҳабби хурд мегардад, пешгирӣ карда шавад. Дар муқобил, карши дунахӣ ё дар пайҳаҳои 40 сантиметр, фазои бешаро барои ташаккули ноб эҷод мекунад ва имкон медиҳад зичии каме баланд (бо фарзияи фаъолияти муносиби боб) танзим карда шавад.</p>\n\n\n\n<h2>Нуқтаҳои амалии карши боби бубӯр</h2>\n<ol>\n<li><strong>Парокунии ҳамворшудани боб:</strong> Аз ҷавҳонкунаки дастӣ бо танбеки дақиқ истифода баред. Зиндагӣ (сатҳнокӣ) дар чуқурӣи номуносиб содиминокӣ-ро паст меорад ва ҳис мекунад, ки миқдори ҷавҳон кофӣ нест. Чуқурии ғайронӣ 3 то 5 сантиметр мувофиқ аст.</li>\n<li><strong>Истифодаи ҷавҳони гирҳандозанда:</strong> Дар баъзе навъҳо, ҷавҳони гирҳандозанда (бо пӯст) ҳаҷми зиҳтро дорад. Агар аз ин навъ истифода мебаред, миқдори килограммӣ-ро то 15 фоизи зиёд кунед.</li>\n<li><strong>Обёрӣи аввали ҷавҳон:</strong> Баъд аз ғайронӣ ва пеш аз ҷавҳонкунии ниҳоӣ, як нӯри обӣ-ро иҷро кунед, то ҷавҳон ба чуқурӣи намноқ расад.</li>\n<li><strong>Ҳамзамониш бо обёрӣ:</strong> Бо кам шудани шиддати обёрӣҳои қатқаатӣ дар оғози давраи рушд (барои назорати ғаллодҳо), дар ҳолати истифодаи миқдори ҷавҳони гирҳандозанда дар гектар камтар (тақрибан 25-30 килограмм) бояд аз зарарзанҳои пеш аз ландагӣ истифода бурд мешавад.</li>\n</ol>\n\n<h2>Саволҳои маъмула (FAQ)</h2>\n<p><strong>1. Оятон ёки зиёд кардани миқдори тобӣ бехи гулранг дар ҳектар ба сифати равған таъсир мерасонад?</strong><br>Дар ҳолати стандартӣ, таъсири мустақим ба фоиз равған надорад, аммо ба истеҳсоли умумии равған дар ҳектар (миқдори ниҳоӣ) таъсир мерасонад. Зичии баланд одатан боиси дони хурдтар ва заифтар мешавад, ки сифати ҷудокунии равғанро дар корхонаҳои дон тобӣ паст мекунад.</p>\n<p><strong>2. Оё дар минтақаҳои коҳистонии баландболоӣ миқдори тобӣ бехро иваз мекунем?</strong><br>Бале. Ба далели паст шудани ҳарорат ва афзоиши дертар, навидҳои кӯтоҳтар ва тезтари мавҷуданд, ки одатан зичии баландтарро талаб мекунанд, то имконияти пӯшиши хокро ба амал оранд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-گلرنگ-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر گلرنگ در هکتار: راهنمای جامع - تصویر 3"/><figcaption>seed rate per hectare crop guirand</figcaption></figure>\n<p><strong>3. Системаи қатрагии қадимӣ аст, чӣ қадар тобӣ бех истифода мебарам?</strong><br>Дар системаҳои қадимии ки тақсимоти об яксон нест, аз ҳадди ақал миқдори тобӣ бех истифода баред (масалан, 25-30 кг барои навидҳои бузург). Бехҳо, ки дар минтақаҳои хушк барои навозҳои хушк ҷойгир мешаванд, бо зичии баланд заиф мемонанд.</p>\n\n<h2>Хулоса</h2>\n<p>Интихоб <strong>Миқдори бехи гулнаранҷ барои гектар</strong> Як қарори чандбурид аст, ки омезиши нависморо, ҳолати обёрӣ ва шароити мазрави дар бар мегирад. Дар умум, фосили бехатар барои аксари нависморо дар Эрон 25 то 45 килограмм аст. Агар аз системаҳои навтави обёрӣ қатраивӣ ва нӯри тибӣ истифода баред, метавонед ба самти нависморои ним-баҳорӣ бо зичии баландтар ҳаракат кунед, то ҳодди истеҳсоли равғанро зиёд созед. Ҳамеша аз бехи ҳавҷ ва бо ҳавҷии баланд истифода баред, то шумораи бехҳои ҳақиқии зинда бо шумораи бехи кӯшодашуда мувофиқат кунад. Барои огоҳ шудан аз омилҳои таъсиррасон ба ҳоҷми истеҳсоли дигар маҳсулот бо зичии гуногун, метавонед мақолаи нуқтаҳои муҳим ҳангоми истифодаи нӯри тибии обёрӣ ва мақолаи <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%aa%d9%88%d8%aa-%d9%81%d8%b1%d9%86%da%af%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми истеҳсоли малина барои гектар: Омилҳо ва роҳҳои зиёд кардан</a> ро омӯзед.</p>\n<p><strong>Моҳияти алоқаманд:</strong> <a href="https://navar-abyari.ir/%D9%87%D8%B2%DB%8C%D9%86%D9%87-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%A8%D8%B1%D8%A7%DB%8C-%DB%8C%DA%A9-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1-%DA%86%D9%82%D8%AF%D8%B1-%D8%A7%D8%B3%D8%AA/">D987D8B2DB8CD986D987 D986D988D8A7D8B1 D8AADB8CD9BE D8A8D8B1D8A7DB8C DB8CDAA9 D987DAA9D8AAD8A7D8B1 DA86D982D8AFD8B1 D8A7D8B3D8AA</a>, <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%ae%d8%b1%d8%a8%d8%b2%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори бехи тарбуз барои гектар + Ҷадвали зичии кортубӣ</a>، <a href="https://navar-abyari.ir/pakhtahosil-yeki-gektar-rahnama-kishovarzon/">pakhtahosil yeki gektar rahnama kishovarzon</a></p>','Микдори бехи гурӯҳи гулранг дар гектар: Пойгоҳи равшан','Дар ин дастур бо омилҳои муайянкунандаи миқдори боби глоранг дар hektar, фарқияти намоишҳо ва шароити обёрӣ бо усули қатрӣ шинос мешавед, то аз намондагӣи оптималӣ ва кам шудани хароҷоти манбаъҳо боварӣ ҳосил кунед.','publish','closed','closed','seeding-rate-colorful-flower-group-hectare',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
