INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима ба нақди ҳофту чуби шубодро бо усули обобарӣи қабул ва зарурати истифодаи лентаи дех</h2>\n<p>Шубод яке аз гиёҳони хушбӯякӣ ва доруии аст, ки аз сабаби хушбӯй ва тазги ахлоқӣ дар бозорҳои дохилӣ ва экспорӣ қобилияти хос дорад. Ин гиёҳ ғайр аз арзиши озуқавии баланд, барои саноати доруӣ ва хушбӯйсозӣ ба таври васеъ истифода меёбад. Барои расидан ба максимали иқтидорнокӣ ва сифати маҳсулот, бояд аз системаҳои обобарии дақиқ, ба монанди лентаи дех истифода баред. Истифодаи ин усул на танҳо ба кам кардани истеъмолоти об мусидат менамояд, балки бо таъмини намнокии якхела дар замин, рушди якхелаи решаҳо ва пешгирӣ аз бемориҳои зиндаҳои қароразӣ имкон медиҳад. Дар ин роҳнамои васеъ, мо ҳамаи ҷанбаҳои техникии ҳофту чуби шубодро бо диққати махсус ба идоракунии обобарӣ мӯҳим менамоем. Мушкили асосӣ дар чуби шубод нигоҳ доштани мувозинати намнокӣ дар замин аст; зеро ин гиёҳ ба хушкӣ ҳассос аст, вале бо шустани шадиди решаҳо он аз ҳаром дучор мешавад. Лентаи дех бо овардани об ба таври навбатӣ ва идорашаванда ин мувозинати нозукро таъмин мекунад ва деҳқонро аз тағйирёбии намнокӣ дур мекунад. Ин масъала дар иқлимҳои нимхушк, ки захираҳои об маҳдуданд, аҳамияти чандбар дорад. Бо истифода аз принсипҳои дуруст, ҳам мусоидат ба вақти омодагии маҳсул ва ҳам сифати афшони дар баргҳоро баланд бардоштан мумкин аст, ки бевосита ба нархи ниҳоии маҳсул таъсир мерасонад. Ҳамин тавр, кам кардани дохилшавии дастӣ дар ҷараёни истеҳсолот миқдори меҳнат заруриро ба ҳадди ақал меорад ва имкони васеъ кардани боғҳои калонро фароҳам меорад. Дар поён, мо ҳамаи марҳалаҳоро, аз омодакунии замин то насб кардани системаи обобарӣ, ҷадвали дақиқи обобарӣ ва ғизоӣ ва муқоисаи иқтисодии ин усул бо дигар гиёҳони хушбӯякро санҷида мекунем, то сурати пурраи идоракунии муосири ҳофту чуби шубодро пешкаш намоем.</p>\n\n<h2>Принсипҳои ҳофту чуб ва омодакунии замини чуби шубод бо дақиқии баланд</h2>\n<p>Муваффакият дар кишти бодагон аз тайёркунии дурусти сохтзор оғоз меёбад. Ин намуд гиёҳ ба хокҳои нӯфусгир, сабуке ва ғанӣ аз моддаҳои органикӣ майл дорад ва pH-и идеалӣ он байни 6 то 7.5 аст. Пеш аз насб кардани системаи ороғ, бояд ноҷӯрҳо аз сохтзор хатарзӯда шаванд ва хок гард ва рӯи хок коркард шавад, то таркиши решаҳо кафолат ёбад. Инчунин, истифодаи бӯҷаҳои солим ва бе илтихом, қадами аввалин барои кишти муваффақ аст. Дар киштҳои механизатсияшуда, риоя кардани фосила байни сатҳҳо (тақрибан 40 то 50 сантиметр) ва фосила байни дарахтҳо (10 то 15 сантиметр) барои расидани нур ба баргҳо ва пешгирӣ аз зичии зиёд зарур аст. Зичии но мувофиқ метавонад боиси ҷарри нисбии зери баргҳо ва эҷоди муҳити муносиб барои рушди пӯсии қарачӣ гардад, ки идоракунии он хеле мушкил аст. Бинобар ин, ҷойгиркунии дарахтҳо бояд бо оморшӯнокии гиёҳ мувофиқат дошта бошад. Инчунин, чуқурии ниҳод бӯҷа ё ниҳол дар муваффакияти кишт нақши калидӣ дорад. Кишти чуқур метавонад рушди аввалинро оҳиста кунад ва кишти сатҳӣ метавонад боиси вайронии бӯҷа ё хушк шудани он гардад. Тавсия мешавад, ки чуқурии ниҳод байни 2 то 3 сантиметр бошад, то пӯшиши муносиб барои нигоҳ доштани намнокӣ таъмин шавад. Дар минтақаҳои гарм ва хушк, истифодаи бастарпӯш (мелҷ-корӣ) бо моддаҳои органикӣ ё пластики шаффоф, дар нигоҳ доштани намнокии хок ва коҳиши рушди ноҷӯрҳо кӯмаки зиёд мекунад. Ин бастарпӯш ба як навъ, бо системаи нӯри банд ҳамкорӣ мекунад ва ҳарорати хокро устувор менамояд.</p>\n<ul>\n<li><strong>Ҷойгиркунӣ ва муносибсозии хок:</strong> Таъмини нӯфускиши мувофиқ ва тоза кардани сахтии сохтзор бо истифодаи шандурӯйӣ, агар зарур бошад.</li>\n<li><strong>Насби системаи нӯри банд:</strong> Ҷойгиркунии лӯлаҳо дақиқан пеш аз ниҳод, барои пешгирӣ аз осеб ба қутриҳо ва сӯроҳҳои андохт.</li>\n<li><strong>Санҷиши сифати бӯҷа:</strong> Интихоби намудҳое, ки ба шароити ороғи камоборӣ ва нурдиҳанда муносибанд ва иҷрои санҷишҳои ниҳол, агар кишт бо бӯҷа анҷом нашавад.</li>\n<li><strong>Тайёркунӣи кимиёвӣ:</strong> Илова кардани миқдори мувофиқи моддаҳои зараррасон барои назорати зараррасонҳои решахӯр пеш аз ғарсониш.</li>\n</ul>\n<p>Муайян кардани зичии мувофиқи ғарсониш ба таври мустақим ба миқдори талаботи системаи нӯри ғармонӣ таъсир мерасонад. Бо зиёд шудани зичӣ, бояд масофаи тақризанҳо камтар шуда ва ҳаҷми камтари об дар ҳар тақризан маҳфуз гардад то аз хунукшавии назарии решаҳо пешгирӣ шавад. Барои ҳисобҳои дақиқи ҳаҷми об ва шумораи тақризанҳои зарурӣ дар як воҳиди сатҳ, омӯзиши роҳнамои  <a href="https://navar-abyari.ir/navor-i-tip-baroi-yek-gektar-chi-qadar/">нӯри ғармонӣ барои як гектар чӣ қадар</a> метавонад ба деҳқонон дар баҳодиҳии арзишҳо ва истиноқти об кӯмак расонад. Ин ҳисобҳо бояд бо назардошти намуди ғармонӣ, фишори даромадии система ва диаметри хатҳои анборкунӣ танзим карда шаванд то пайвастагии фишор дар тамоми давраи ғармонӣ таъмин гардад.</p>\n\n\n<h2>Нақши муҳими нӯри ғармонӣ дар идоракунии намдорӣ ва ғизогузории риҳан</h2>\n<p>Системаи нӯри ғармонӣ бо сабаби парокандагии якхелаи об дар минтақаи решагӣ беҳтарин имконият барои ғарсониши риҳан аст. Ин система боиси он меъшавад, ки намдорӣ ҳамеша дар амикии муайяни хок, ки решаҳо дар он ҷой доранд, нигоҳ дошта мешавад. Азбаски риҳан наботате мебошад, ки ба хушкӣ вақтӣ ҳассос аст ва решаҳои кӯтоҳ дорад, нигоҳ доштани намдории сатҳӣ ва амиқ бо нӯри ғармонӣ хатари фишори обиобро ба ҳадди ақалл мерасонад. Баръакс, обёркунӣ бо ғармоб боиси пӯсидаги решаҳо ва коҳиши хӯби донҳо мебошад ва инчунин ба рафъи сахти манбаъҳои об оварда мерасонад. Барои фаҳмиши беҳтар механизми кор кардани ин системаҳо ва маврумҳои асосии обёркунии дақиқ, шумо метавонед ба мақола <a href="https://navar-abyari.ir/nori-tipa-kalmos-robnameyi-obyorii/">нӯри ғармонӣ барои калмуши романтиқӣ обҳу</a> Манорӯҳ карданест, ки ба таври сода муфассалатии тавсифи ҷараёнҳои обёрӣро меомӯзед. Яке аз муносибати зерини системаи обёрӣ бо ноқилҳои нафасгирӣ (дроп) имкони парҳез намудани маҳлули ғизоӣ мебошад. Базилики ҷаъдор (Oregano) намуде отагӣ аст, ки ба парҳези бо маҳлули ғизоӣ тақсимшуда хушдустанд ва ба маҳлули ғизоӣ бо консентратсияи баланд ҷавоби хуб намедиҳад. Бо воридкунии маҳлули ғизоии ғализон аз рӯи қубурҳои нақили даропӣ, маводи ғизоиро мустақиман дар минтақаи риштадор бошудан мумкин аст. Ин ба ҷабиши тезтари кислоти фоливӣ, оҳан ва мис кӯмак мекунад ва ноқилиҳо ғизоиро ба таври суръат ба роҳ меорад. Инчунин, идоракунии pH-и маҳлули ғизоӣ барои пешгирии ҷамъшавии элементҳои микро дар нозукҳо муҳим аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-ریحان-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت ریحان با آبیاری قطره‌ای - تصویر 1"/><figcaption> усули ғайрбод, ғайрбод бо нақили даропӣ, барномаи обёрӣ, базилик</figcaption></figure>\n\n<h2>Барномаи тайёркунии вақти обёрӣ дар марҳилаҳои гуногони рушди базилик ва ноқилиҳои муҳим</h2>\n<p>Идоракунии дурусти вақти обёрӣ калиди истеҳсоли маҳсулоти хобмалкӯб аст. Базилик дар ҳар марҳилаи рушди ӯ ба об ниёзҳои гуногун дорад. Дар марҳилаи аввали рушди отагӣ, ниёз ба об кам аст ва зиёдшудани он метавонад ба дарозшудани зиёди ғовҳо (стеблҳо) оварда расонад. Дар марҳилаи рушди фаъол, бо тезии тезии баргҳо, миқдори об бояд зиёд шавад. Аммо пеш аз ҷамъоварӣ, барои зиёд шудани консентратсияи эфир ва сифати тиҷоратӣ, обёрӣ бояд кам ва маҳдуд шудан. Тағйирёбии стратегияи обёрӣ боиси мешавад, ки отагӣ энергияи худро ба истеҳсоли пайдои маводди ароматӣ равона кунад, на ба рушди отагӣ. Маъруф ба ҳаҷми об, такрори бароришҳои обёрӣ низ хеле муҳим аст. Обёрии зиёд бо ҳаҷми кам нисбат ба обёрии камбоҳаҷм, барои базилик беҳтар аст, зеро ба ниҳолшавии такрории заминаки баргҳо оварда намерасонад.</p>\n<ol>\n<li><strong>Марҳилаи баргушудан:</strong> Воридкунии оби кам-консентратсия ва идораи он барои рушди риштаҳои қавӣ ва пешгирии тағйирот аз ғайрбод.</li>\n<li><strong>Марҳилаи рушди отагӣ:</strong> Зиёд шудани ҳаҷми об ва шумораи бароришҳои обёрӣ барои дастгирӣ аз рушди тезии ғавуҳҳо ва истеҳсоли бештари баргҳо.</li>\n<li><strong>Марҳаби пеш аз ҷамъоварӣ:</strong> Кам шудани намдӣ барои марказишавии моддаҳои пардашаванда ва беҳтар шудани хӯри маҳсулот, одам 7 то 10 рӯз пеш аз ҷамъоварӣ.</li>\n</ol>\n<p>Бетарин ҳамои баргузории обории банди рӯлока, саҳорои субҳ ва шабуҳои дер аст то тамокурии сатҳӣ кам шавад. Бо назардошти тағйиротҳои иқлимӣ, бояд нақшаи оборӣ ҳафтабарҳа дубора омӯзашавад. Дар минтақаҳои гарм, метавонад дар қуллаи тобистон, ниёз ба обории рӯзона бошад, дар ҳоле ки баҳор ва тирамоҳ, фосилаи навбатҳо метавонад то 2 то 3 рӯз зиёд шавад. Ҳамроҳи идоракунии об, диққат ба ғизои растани низ муҳим аст. Рихан ба нитроген ҳассос аст ва мувозанати P ва K бояд дар оби оборию маҳлул-фавқулода риоя шавад. Ин чиз боиси мегардад, ки моддаҳои ғизоӣ ба тарафдори рӯишаҳои тоза ва фаъол дар минтақаи намидори банди рӯлока баъди торафтар ҷазб шаванд. Истиҳоми маҳлулҳои ғизоии органикӣ низ метавонад сифати данаҳоро беҳтар кунад.</p>\n\n\n<h2>Идоракунии майдони деҳқони, парвариши системаи оборӣ ва муқоиса бо дигар растаниҳои хушибӯи</h2>\n<p>Парвариши системаи банди рӯлока, бахусус дар шароити хокӣ намкин, аз ҷамъшавии намакҳо пешгирӣ мекунад. Филтрасияи мувофиқ ва шустушӯи мултимарот, умри чангкунониро таъмин мекунад. Интиқофи лӯлаҳои банди рӯлока яке аз мушкилоти одам аст, ки дар сурати наздикӣ накардан, ба хушкшавии маълуми рӯишаҳои рихан мусаррафи мекунад. Машоҳида дорад, ки аз филтрҳои торӣ бо тасвири дақиқ ва инчунин аз системаҳои зиди ҷамъшавӣ дар мағозаи ғизо истифоҳа бошад. Дар паҳлӯи рихан, коррони дигар растаниҳои хушибӯи низ дар даштҳои деҳқонӣ имконпазир аст. Барои мисол, тадқиқот <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%b1%d8%b2%d9%85%d8%a7%d8%b1%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори ҷамъоварии размарин дар ҳектар</a> Ин метҳод метавонад намунаи монан барои идоракунии иқтисодии парҳези растаниҳои доруворӣ бошад, гарчанде ки шароити рушди rozmarin аз базилка сахттар аст. Rozmarin ба хушкӣ иқдормандтар аст, вазе базилка банамъуффафои устувор ниёз дорад. Фарамоиши фарқияти рафъан байни ин ду растани дар барномарезии деҳкории муҳим аст. Инчунин, таҳлили маълумоти иқтисодии дигар маҳсулот метавонад дидгари беҳтари даромадатӣ эҷод кунад. Ба наздикӣ, мақола <a href="https://navar-abyari.ir/lentil-yield-per-hectare-iraq/">lentil yield per hectare iraq</a> Метавонад муқоисаи даромадатаии растаниҳои хушбӯй ва дони дар климатҳои монанро пешниҳод кунад. Базилик сабаби давраи кӯтоҳи парҳез ва имкони ҷамъоварии чанд маротиба дар фасл, ба имконияти ҷоиб барои деҳқонон табдил ёфтааст. Бо идоракунии дуруст, метавон дар ҳар гектар чанде тонна базилики тоза ё хушк бо сифати савдоӣ истеҳсол кард. Нуктаи охирин дар бораи идоракунии зараррасониҳо аст; дар базилик, зараррасониҳои муҳити пашмон ва гилханҳои сурх муфит аст, ки дар шароити намудори баланди хат, рушди онҳо тезшавӣ мекунад. Бинобар ин, нигоҳ доштани намудории хок набояд ба намудории наздикати баланди тавъи барои расад; ҳавои муфити хат зарур аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-ریحان-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت ریحان با آبیاری قطره‌ای - تصویر 2"/><figcaption>усулҳои парҳез сурати оғози дилӣ расадҳо наздии базилик</figcaption></figure>\n\n<h2>Ҷавоб ба саволҳои оммавии деҳқонон дар бораи парҳези базилик бо навири дилӣ</h2>\n<p><strong>Оё парҳези базилик бо оғози сатҳӣ мумкин аст?</strong> Ҳа, вале фаъолият ва сифати маҳсулот қатъи кам мешавад ва хатари бемориҳои зеришиҳо баланд мешавад. Оғози сатҳӣ ба тағйиротҳои шадиди намудорӣ оварда мерасонад, ки барои решаҳои нозуки базилик зараррасан аст.</p>\n<p><strong>Фосилаи навири дилӣ то реша қадар аст?</strong> Маслаҳат дода мешавад, ки ин фосила аз 5 то 10 сантиметр бошад, то об бевосита ба минтақаи реша расад. Фосилаи бештар ба талафоти об дар банди бефаъол оварда мерасонад ва фосилаи камтар метавонад боиси задани реша гардад.</p>\n\n<p><strong>Дарозаи муддат аз парвариш то ҳосилкуни риҳан чанд аст?</strong> Ба вобаста ба шароити иқлими, барои ин кор 60 то 90 рӯз вақт лозим аст. Дар минтақаҳои гармтари, рафъи вобаста зудтар аст ва дар минтақаҳои сард, ин муддат метавонад то 120 рӯз зиёд шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-ریحان-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت ریحان با آبیاری قطره‌ای - تصویر 3"/><figcaption>усулҳои парвариш, ороиш бо усули ноб, расмиятномаи ороиши ҳосил, риҳан</figcaption></figure>\n<p><strong>Оё метавон аз навишҳои кимиёвии консентратсияи баланд барои риҳан истифода бард?</strong> Не, риҳан ба тузӣ ҳассос аст. Истифода аз ҳалкунандаҳои ғизоӣ бо EC-и баланд сабаби сӯзидани реша ва кам шудани сифати эфирро мекунад. Беҳтар аст, ки аз консентратсияҳои мулоим ва такрори зиёд истифода шавад.</p>\n\n<p>Барои фаҳмиши беҳтари қобилияти парвариш ва хароҷоти вобаста, баррасии додаҳои вобаста ба гиёҳҳои дигар, масалан <a href="https://navar-abyari.ir/oat-yield-per-hectare-guide/">oat yield per hectare guide</a> метавонад нуктаи назарро иқтисодии беҳтар пешниҳод кунад. Ин дастураҳо ба деҳқон кӯмак мерасонанд, ки бо муқоисаи хароҷоти истеҳсолот, фоидаи холии риҳанро нисбати дигар маҳсулот ҳисоб кунад. Хулоса мешавад, ки парвариши риҳан бо усули ноб, сармоягузории доимӣ аст, ки бо назорати мӯддат ва танзими дақиқ, маҳсулоти сифатдор ва фоидароварро ба бор меорад. Бо иҷрои асосҳои дар матнзикридаршуда, метавон интизор шуд, ки ҳам ҳаҷми самаранокии об зиёд шавад ва ҳам сифати тиҷоратии риҳан дар синфи содиротӣ ҷойгир шавад. Диққати ба ҳарфҳои дақиқ дар омодагии замина ва расмиятноми ороиш, фарқияти асосӣ байни як мӯзъаи оддӣ ва мӯзъаи бо самаранокии баланд мебошад.</p>','Рӯйхати ҷумҳури ва махсуси парҳези реҳан бо усули обёрӣи қатқатона ва навигии Tip','Дар ин мақолаи муфассал бо асосҳои партобидани байзонон (риҳон) ва системаи наворӣ ошно шавед. Таҳқиқи пурраи фосилаҳои ниҳолпардозӣ, барномаи вақтии обёрӣ дар марҳилаҳои рушд ва ҳалли мушкилоти маъмул дар бӯстонҳои байзонон.','publish','closed','closed','royxati-kash-ti-rehan-ba-oboriy-qudro-i-navi-tip',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
