INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин рӯйхат, мо роҳнамоии пурра ва махсусро барои парҳези реҳан бо истифода аз системаи ҳозири обёрӣи қатқатона ва навигии Tip муаррифӣ мекунем. Ин маълумот ба деҳқонон кӯмак мерасонад, то ҳосили беҳтарашонро бо истифода аз технологияи ҳозири AFP ва усули навигии Tip ба даст оваранд.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
