INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррарот: Аҳамияти масоҳати лавҳаи лентавӣ дар карбонкунии хурма (таваби)</h2>\n<p>Хурма (таваби) ҳамчун яке аз сабзиёти бисёрарзиш бо талаботи баланд дар бозори дохилӣ, ба идоракунии дақиқи манбаъҳои об ва нуур ниёз дорад. Интихоби дуруст <strong>масоҳати лавҳаи лентавӣ</strong> ва ҷойгиркунии сатҳҳо, бевосита ба таъмини рутбҳои реша ба об, миқдори табқуён ва дар натиҷа ҳаҷми ҳосил дар ҳар гектар таъсир мерасонад. Дар усулҳои муосири оборӣ, истифодаи лавҳаи лентавӣ ба ҷои қутта-қуттаи нуқтавӣ омода шудааст, ки ҳам хароҷоти насбкунӣ-ро кам мекунад ва ҳам тақсимоти баробаробии обро дар назди рутбҳо кафолат мекунад.</p>\n<p>Ҳамчунин, барои онеҳое, ки дар марҳилаи тарҳрезии системаи обории худ қарор доранд, омӯзиши роҳнамои умумӣ дар бораи зиёд кардани самаранокии лавҳаи лентавӣ метавонад назари беҳтари иқтимодҳои пинҳонаи ин система-ро ба шумо диҳад. Дар зир мо тафсилоти техникӣ ва меъёрҳои тиллоии ин масоҳатгузориро баррасӣ мекунем.</p>\n\n\n\n<h2>Асосҳои ҷойгиркунии сатҳӣ ва масоҳатгузорӣ дар карбонкунии хурма (таваби)</h2>\n<h3>Меъёрҳои тавсияшуда барои масоҳати байни сатҳҳо</h3>\n<p>Муайян кардани масоҳат байни сатҳҳои хурма (таваби) ба шартҳои иқлимонӣ, навъи бодир ва системаи кишоварзӣ вобаста аст. Одатан, масоҳат байни сатҳҳо тақрибан 60 то 80 сантиметр тавсия дода мешавад. Ин масоҳат бояд ба таври чунин бошад, ки имкони гузаштани кишоварзӣ-и хурд ва ҷамъоварии дасти ҳосил бе зарар расонидан ба бутавораҳо вуҷуд дошта бошад. Агар аз системаҳои механиковарзӣ истифода баред, масоҳатгузорӣ бояд бо андозаи траверс трактор ё ҷамъовар мувофиқат кунад.</p>\n<h3>Таъсири фосила бар рақобати решаҳо ва қабули об</h3>\n<p>Яке аз масъалаҳои асосӣ дар парҳези zichи қаламон, рақобати решаҳои наздик барои ҷалби об ва моддаҳои ғизоӣ мебошад. Агар <strong>фосилаи наварбандии дрип</strong> тавассути ҳисобкунии дуруст иҷро нашавад, метавонад қисматҳое аз замин хушк монанд ва қисматҳои дигар то ҳадди худ шаванд. Наварбандии дрип бо ин ки обро бо шакли наварбандии танӯб дар қад-қади роҳ бар меоварад, симои мои-хушкро маҳдуд менамояд. Бинобар ин, маркази ин симои мои-хушк бояд дақиқан зер ҷои ҷойгиршавии решаҳои асосии нишинӣ бошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-طالبی-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت طالبی: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>фосилаи наварбандии дрип чинҷи ҳарфҳои нишинӣ қаламон</figcaption></figure>\n\n<h2>Фосилаи наварбандии дрип дар парҳези қаламон: меъёрҳои дақиқ</h2>\n<h3>Муайян кардани фосилаи техникӣ аз наварбандии дрип то нишинӣ</h3>\n<p>Баръъки себзеҳои дигар, қаламон ҳисси баланд ба бемориҳои занбӯрӣ-заминавию доранд, ки нам мондани пайвастаи барг ва қола метавонад омили таъкид додани онҳо бошад. Аз ин рӯ, фосилаи наварбандии дрип аз нишинӣ наметавонад аз ҳад наздик бошад, то аз бозбоз нам шудани ҷойҳои пайвасти қола бо замин пешгирӣ шавад. Меъёр тиллоӣ барои қаламон, фосилаи 10 то 15 сантиметрӣ аз ҷои нишастан нишинӣ мебошад. Ин фосила, мувозинатро байни дастрасии решаҳои парвандашаванда ба об ва нигоҳ доштани хушкӣи нисбии қола эҷод мекунад.</p>\n<ul>\n<li><strong>Фосила 10 сантиметр:</strong> Барои хокҳои сабук ва рехарӣ мувофиқ аст, ки дар онҳо ғафсолии об ба таври амудӣ тезӣ меавад. Дар ин ҳолат, решаҳо бояд тезтар ба риштаи об бирасанд.</li>\n<li><strong>Фосила 15 сантиметр:</strong> Барои хокҳои лойгумӯш (лестист) ва гилӣ мувофиқ аст, ки дар онҳо ғафсолии об оҳистатар меавад. Ин фосила имкон медиҳад, ки минтақаи шӯр (миёнаи хушк) чуқуртар мешавад ва решаҳои чуқуртар низ обнок мешаванд.</li>\n</ul>\n\n\n\n<h3>Риштаи ягона ё дугона?</h3>\n<p>Яке аз саволҳои бениҳоят оддӣ байни кишовонандагон ин аст, ки оё барои ҳар як чанчор аз як риштаи капиллярӣ истифода барем ё ду ришта? Дар парвариши карбаз, бо сабаби афзоиши ҷанбаҳои зиёд ва тавлӯт ҳосил шудани дарахҳо, истифодаи <strong>ду риштаи капиллярӣ</strong> дар ду тарафи чанчор (фоилаи 10 то 15 сантиметр аз ду ҷониб) одатан беҳтар аст. Ин тартибот пошоҳии минтақаи решагиро (минақаи реша) 360 дараҷаӣ менамояд ва аз паст шудани ҳосил дар як самти муайян пешгирӣ мекунад. Албатта, агар фосилаи раводҳо хеле кам бошад, шумо метавонед маҷбур шавед аз як риштаи марказӣ истифода баред, аммо дар ин ҳолат бояд сарҷавии ришта баландтар бошад, то пошавии муносиб таъмин шавад.</p>\n\n<h2>Нуктаҳои амалӣ дар насб ва идоракунии навири тиб барои тарбузи шаҳриҳои</h2>\n<h3>Омодакунии забони ғайрикорӣ</h3>\n<p>Пеш аз насби навр, сатҳи замин бояд ҳамвор карда шуда бошад. Носозие дар баландии зиёда аз 2-3 сантиметр дар давоми боғзор метавонад боиси обизёнии нуқтаҳои поёнӣ ва камобии нуқтаҳои баланд гардад. Агар боғзор шуднок бошад, истифодаи плагҳои фавосанҷандар дар анҷоми наворҳо барои танзими фишори система лозим аст. Шумо метавонед барои фаҳмиши беҳтари ҷойгиршавии физикӣ ва ҷойгиршавии қисмҳои система ба мақола <a href="https://navar-abyari.ir/navori-tipi-ob-yari-plakdor/" target="_blank">Навори наворро ба об тиб плагдор</a> муроҷиат кунед, ки ба шарҳи алоқаи шифтҳо ва пайвастаҳо дахл дорад.</p>\n<h3>Интихоби раҳи мувофиқи навори тиб</h3>\n<p>Барои тарбузи шаҳриҳои, раҳи навори тиб одатан дар байни 2 то 4 литр дар соат барои ҳар метри дарозӣ тавсия дода мешавад. Ин раҳ бояд асос гардиди ниёзҳои рӯзонаи ғилоф (ки дар лаҳзаи кӯҳарӣ тақрибан 50 то 70 литр барои ҳар навошт аст) ва шумораи навоштҳо дар метри дарозии сафҳи ҳисоб карда шавад. Масалан, агар масофаи навоштҳо дар тӯли сафҳи 30 сантиметр бошад, барои ҳар метр 3.3 навошт вуҷуд дорад. Бо раҳи 3 литр дар соат, тақрибан 1 литр дар соат ба ҳар навошт ба замин ворид мешавад, ки барои давраи рушдӣ 12 соатӣ, 12 литри об ба ҳар навошт пешниҳод мешавад. Ин ҳисобҳо бояд бо самаранокии таъмини оби замони шумо мутобиқ гардонида шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-طالبی-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت طالبی: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>Фосили навори тиб, ҷойгиршавии сафҳ, ғилофи тарбузи шаҳриҳои</figcaption></figure>\n\n\n\n<h3>Пӯшиши равишҳо ва ҳимоят аз рӯшноӣ</h3>\n<p>Равишҳои полиетиленӣ, ки ба рӯшноии бевоситаи офтоб дастрасанд, умри кории худро аз даст медиҳанд ва ҳариф мегарданд. Дар кишти кӯби, ки аввал ботлок, сипас муҳкам мешавад, тавсия мекунад аз равииҳҳои UV-stable истифода баред ё дар марҳилаҳои ибтидоӣ равишҳоро бо пӯшиши пластикии тарро ё хокпории кӯтоҳ пӯшонед. Инчунин, бо пешравии меъёри гиёҳ, сипари табиии кӯб бештар равишро аз рӯшноии бевосита ҳимоят мекунад, вале дар боғҳои каммаҳсул ё дар фаслҳои гарм, нигаҳдории шикори равиш аз дарази равиш вобаста ба муштароҳон муҳим аст.</p>\n\n<h2>Саволҳои дархӯрдашуда (FAQ)</h2>\n<h3>Оё фосилаи равишҳо дар замини вазнин фарқ дорад?</h3>\n<p>Бале, дар заминаи вазнин ва зехши заиф, фосилаи равиш аз боқотак бояд каме зиёдтар (15-20 сантиметр) бошад, то аз ғарқ шудани ҷамъшудаи решаи асосӣ пешгирӣ шавад. Дар заминаи сабук, фосилаи 10 сантиметр кофист, зеро об тезтар ҷарф мекунад ва мадоди таъсиррасонии он маҳдудтар аст.</p>\n<h3>Оё мо метавонем аз равишҳо барои кишти омезишандаи кӯб ва помидор истифода барем?</h3>\n<p>Истифода аз равиши умумӣ барои кӯб ва помидор дар як сутун ниҳоӣ тавсия намешавад, зеро нақши истифодаи об ва ҳассосият ба бемориҳои ин ду гиёҳ фарқ мекунад. Беҳтар аст сутунҳо ҷудо бошанд ва ҳар яке, вобаста ба ниёзи худ, фосила ва срағи истифодаи хусусӣ дошта бошанд. Барои шиносӣ ба ҷузъиёти обёрӣ бо равии чакшуори сабзавотҳои монанд, шумо метавонед мақола <a href="https://navar-abyari.ir/detailed-cucumber-drip-irrigation-guide/" target="_blank">Роҳнамои умумии обёрӣ бо равии чакшуорӣ барои кӯби (гурдаи)</a> роҳнам карда шавед, ки принсипҳои монандро барои сабзавоти мевадор фармоиш мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-طالبی-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت طالبی: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>фосилаи тасмаи қатқатии сафҳаро ҷойгир кардани фармон барои каду хӯрокӣ</figcaption></figure>\n<h3>Беҳтарин вақти насби тасмаи қатқатӣ пеш аз ё пас аз ҷашондан аст?</h3>\n<p>Беҳтарин роҳ, насби тасмаи қатқатӣ пеш аз ҷашондан аст. Ин кор имконияти сохтани қатори мувофиқро бо ёрии асбоби дорад, то ки тасма бо хок пурра дар тамос бошад. Насб пас аз ҷашондан боиси пайдо шудани фосилаҳои ҳавоӣ зер тасма мешавад, ки метавонад ба доридани ҳаво ва коҳиши самаранокӣ система одаш дорад. Фаразони насби дуруст дар <a href="https://navar-abyari.ir/%d8%b7%d8%b1%db%8c%d9%82%d9%87-%d9%86%d8%b5%d8%a8-%d9%86%d9%88%d8%a7%d8%b1-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%aa%db%8c%d9%be/" target="_blank">Роҳи насби тасмаи оборӣ-қатқатӣ</a> шарҳ дода шудааст, ки қадам ба қадам марҳилаҳои пайвастаро тавзеҳ медиҳад.</p>\n\n<h2>Хулоса</h2>\n<p>Дархости натиҷаи мувофиқ аз парвариши каду хӯрокӣ, лозимият ба диққат ба ҷузъиёти муҳандисии системаи оборишро дорад. <strong>Фавоси нӯриппа</strong> Ин на танҳо як адади собит, балки мутағаййирест, ки бояд вобаста ба навъи хок, иқлим ва идоракунии кортӯҳҳо танзим шавад. Ба таври мухтасар, фавоси 10 то 15 сентиметрӣ аз ниҳоки ду нӯриппа, сарфшиносии 3 литр дар соат ва овардани об дар вақти муайян, формулаи бартарист, ки хароҷоти истеҳсолро коҳиш дода ва сифати пӯст ва гӯшти шаҳмарбофро зиёд мекунад. Бо пайгирӣ кардани саломатии шахтаҳо ва плускаҳо ва риояи асосҳои нигоҳдорӣ, шумо метавонед нӯриппаи худро бартарии зиёдтар аз як фаслро дар бар меоварад.</p>\n<p>Барои кساني, ки мехоҳанд мутобиқсозии системаи обёрӣ худро бо усулҳои марказнокшуда ва такмилшуда омезиш диҳанд, таҳқиқот <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%AC%D9%88-%D8%B4%D8%B4-%D9%BE%D8%B1-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/" target="_blank">Ҳаҷми хариди ҷав ва шарбатбар дар гектар</a> метавонад дониши беҳтарро дар бораи фарқи самаранокии сабзавот бо донаи ҳиллаҳо барои шумо пеш ояд ва ба муқоисаи иқтисодии кортӯҳҳо кӯмак расонад.</p>','Фосилаи ҷоҳи карики кабоби таълибӣ: меъёрҳои тавсияшуда','Муайяни фاصلهи мувофиқи шинаҳои обунок дар кӯҳнак, яке аз муҳимтарин омилҳои таъсирбахш ба рушди растанӣ ва сифати маҳсулот мебошад. Дар ин мақола мо меомӯзем, ки меъёрҳои тавсияшуда, ҷойгиркунии сафиҳо ва нуқтаҳои амалии насб мавҷуданд, то беҳтарин самаранокии обуноккунии тамғавиро дар кӯҳнаки кӯҳнакаро таҷриба кунед.','publish','closed','closed','fosilai-johi-kariki-kabobi-talibi',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
